INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_famine_blanche_tout_se_mange', 'Tout se mange', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_bouche-sans-fond', 'Bouche sans fond', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, passif","activation":null,"texte_court":"tu digères sans dommage immédiat des aliments impropres ou des matières organiques normalement indigestes, mais encore nutritives. Ni métal, ni énergie, ni phénomène surnaturel.","texte_reference":"Bouche sans fondProfil: 1 PTV • DON • Marqué • SR/R • PassifLe porteur peut consommer sans dommage immédiat des matières organiques, aliments impropres ou substances normalement impossibles à digérer mais encore nutritives. Cela ne permet pas encore de manger métal, énergie ou phénomènes surnaturels.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Marqué","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_devorer-la-matiere', 'Dévorer la matière', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA","activation":null,"texte_court":"tu manges au contact un petit volume de matière non vivante (serrure, chaîne, plaque mince, roche). Une matière surnaturelle ou un artefact oppose sa Puissance. Jamais sur un vivant.","texte_reference":"Dévorer la matièreProfil: 2 PTV • DON • Envahi • R • 1 PALe porteur peut consommer une petite quantité de matière non vivante au contact : serrure, chaîne, plaque mince, morceau de roche ou volume équivalent. Une matière surnaturelle ou un artefact oppose sa Puissance. Ne fonctionne pas directement sur un être vivant.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Envahi","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_devorer-l-energie', 'Dévorer l''énergie', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA, 1/scène","activation":null,"texte_court":"tu dévores une source d''énergie locale accessible (batterie, feu, chaleur concentrée, charge électrique, manifestation énergétique simple). Elle cesse ou se vide. Un phénomène surnaturel oppose sa Puissance.","texte_reference":"Dévorer l’énergieProfil: 2 PTV • DON • Envahi • R • 1 PA • 1/ScèneLe porteur dévore une source énergétique locale directement accessible : batterie, chaleur concentrée, feu, charge électrique ou manifestation énergétique simple. L’effet cesse ou se vide selon sa nature. Un phénomène surnaturel oppose sa Puissance.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Envahi","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_devorer-l-espace', 'Dévorer l''espace', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 1 PA, 1/scène","activation":null,"texte_court":"tu dévores la distance jusqu''à un point perçu à courte portée et tu y apparais. Ne traverse ni scellement dimensionnel, ni frontière de plan, ni enceinte conçue contre ce déplacement.","texte_reference":"Dévorer l’espaceProfil: 3 PTV • DON • Au bord • R • 1 PA • 1/ScèneLe porteur dévore la distance entre lui et un point directement perçu à courte portée et y apparaît immédiatement. Cela ne traverse pas un scellement dimensionnel, une frontière de plan ou une enceinte explicitement conçue pour empêcher ce type de déplacement.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Au bord de la Rupture","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_devorer-le-pouvoir', 'Dévorer le pouvoir', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"après avoir résisté à un Talent surnaturel actif, tu en dévores le reste. Sa source ne peut plus te viser avec ce même Talent jusqu''à la fin de sa prochaine activation. Rien n''est copié ni appris.","texte_reference":"Dévorer le pouvoirProfil: 3 PTV • DON • Au bord • R • Réaction 1 PA • 1/ScèneAprès avoir résisté avec succès à un Talent surnaturel Actif précis, le porteur peut en dévorer la manifestation résiduelle. La Source ne peut pas employer exactement ce même Talent contre lui jusqu’à la fin de sa prochaine activation. Le Talent n’est ni copié ni appris.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Au bord de la Rupture","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_famine_blanche_devorer_le_vivant', 'Dévorer le vivant', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_devorer-la-vie', 'Dévorer la vie', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, R, 1/round","activation":null,"texte_court":"quand ta morsure, ta prédation ou ton ingestion directe inflige au moins 1 PV réel à un vivant, tu récupères 1 PV. Aucun soin sans vrai prélèvement.","texte_reference":"Dévorer la vieProfil: 2 PTV • DON • Marqué • R • 1/roundLorsqu’une morsure, prédation ou ingestion directement prise sur une créature vivante lui inflige au moins 1 PV réel, le porteur récupère 1 PV, au maximum une fois par round. Aucun soin sans véritable prélèvement de vivant.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Marqué","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_devorer-la-douleur', 'Dévorer la douleur', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA, 1/scène","activation":null,"texte_court":"jusqu''à la fin de la scène, ignore une conséquence due seulement à la douleur, aux spasmes ou au choc. PV, mutilations et dommages restent.","texte_reference":"Dévorer la douleurProfil: 2 PTV • DON • Marqué • SR/R • 1 PA • 1/ScèneLe porteur isole puis consume la douleur d’une blessure. Jusqu’à la fin de la scène, une conséquence due uniquement à la douleur, aux spasmes ou au choc douloureux peut être ignorée. Les PV, mutilations et dommages structurels restent.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Marqué","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_devorer-la-mecanique-du-corps', 'Dévorer la mécanique du corps', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA, 1/scène","activation":null,"texte_court":"une fonction corporelle non vitale, inutilisable seulement parce que la structure est rompue, fonctionne jusqu''à la fin de la scène. La blessure revient ensuite avec toutes ses conséquences.","texte_reference":"Dévorer la mécanique du corpsProfil: 3 PTV • DON • Envahi • R • 1 PA • 1/ScèneLe porteur dévore temporairement l’impossibilité mécanique créée par une blessure. Il choisit une fonction corporelle non vitale devenue inutilisable uniquement parce que la structure est rompue ; elle fonctionne jusqu’à la fin de la scène. La blessure n’est pas soignée et revient ensuite avec toutes ses conséquences.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Envahi","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_devorer-sa-mort', 'Dévorer sa mort', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction, 1/scénario","activation":null,"texte_court":"au lieu de franchir ton seuil de Mort, tu tombes à 0 PV, Stabilisé. +1 Corruption Vhodhal automatique ; Bascule si l''Intégrité est atteinte.","texte_reference":"Dévorer sa mortProfil: 3 PTV • DON • Au bord • R • Réaction • 1/ScénarioLorsqu’une conséquence devrait lui faire franchir son seuil de Mort, le porteur dévore sa propre mort immédiate et tombe à 0 PV, Stabilisé. Il gagne automatiquement +1 Corruption Vhodhal ; si l’Intégrité est atteinte, Test de Bascule immédiat.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Au bord de la Rupture","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_famine_blanche_ecume', 'Écume', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Ressort face aux autres contagions (Fontaine, Germination, Loge) : ici, c''est le corps du porteur qui contamine, sans rite ni Souillure."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_ecume-blanche', 'Écume blanche', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, R, 1 PA","activation":null,"texte_court":"tu produis une écume chargée de ta Famine. Elle sert de vecteur à tes Dons ou à un rite, ou se garde quelques minutes comme contaminant. Aucun DGT par elle-même.","texte_reference":"Écume blancheProfil: 2 PTV • DON • Marqué • R • 1 PALe porteur produit une écume blanche chargée de sa Famine. Elle peut servir de vecteur à ses Dons, à un rite ou être conservée quelques minutes comme substance contaminante. Elle n’inflige aucun DGT générique à elle seule.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Marqué","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_famine-blanche_faim-contagieuse', 'Faim contagieuse', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, passif","activation":null,"texte_court":"quand ton écume, ton sang ou ta matière biologique entre dans une blessure ou est ingérée, tu peux exposer la cible à Vhodhal (Vigueur + Constitution contre 15), une fois par cible et par scène.","texte_reference":"Faim contagieuseProfil: 2 PTV • DON • Envahi • R • PassifLorsque l’écume, le sang ou une autre matière biologique du porteur entre réellement dans une blessure ou est ingérée, il peut exposer volontairement la cible à Vhodhal : Vigueur + Constitution difficulté 15, une fois par cible et par scène.","lore":null,"groupe_actuel":"Vhodhal — Famine Blanche","kind":"DON","profondeur":"Envahi","source":"vhodhal","famille":"Famine Blanche","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'corruption', 'corruption_culte_la_loge_d_ecume', 'Culte — la Loge d''Écume', NULL, '{"nature":"corruption","chemin":["Vhodhal — la Famine Blanche","Culte — la Loge d''Écume"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_la_loge_d_ecume_les_miettes', 'Les Miettes', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_recolter-les-miettes', 'Récolter les miettes', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 15","activation":null,"texte_court":"après un sacrifice valide sur un Autel d''Écume, tu reçois une Miette de Vérité, une propriété surnaturelle simple que la victime possédait réellement. Elle dure jusqu''au prochain repos prolongé ; tu n''en portes qu''une.","texte_reference":"Récolter les miettesProfil: 1 PTV • RITE • SR/R • Rituel • Souillure 15Après un sacrifice valide accompli sur un Autel d’Écume, le cultiste reçoit une Miette de Vérité : une propriété surnaturelle simple réellement possédée par la victime. Une Miette dure normalement jusqu’au prochain repos prolongé et une seule peut être portée.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_partage-de-l-ecume', 'Partage de l''Écume', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 18 ; requiert Récolter les miettes","activation":null,"texte_court":"la Miette peut revenir à un autre initié présent. Une propriété assez simple peut se diviser en deux versions amoindries (choix du MJ), jamais se dupliquer.","texte_reference":"Partage de l’ÉcumeProfil: 2 PTV • RITE • SR/R • Rituel • Prérequis : Récolter les miettes • Souillure 18La Miette produite peut être attribuée à un autre initié participant. Une propriété suffisamment simple peut être divisée en deux versions amoindries décidées par le MJ, jamais dupliquée intégralement.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Récolter les miettes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_choisir-la-bouchee', 'Choisir la bouchée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 18 ; requiert Récolter les miettes","activation":null,"texte_court":"tu désignes une famille de propriété (perception, mouvement, défense, élément, physiologie, pouvoir mental) ; le MJ choisit une Miette cohérente. Jamais un Talent précis.","texte_reference":"Choisir la bouchéeProfil: 2 PTV • RITE • SR/R • Rituel • Prérequis : Récolter les miettes • Souillure 18Le cultiste désigne une famille de propriété recherchée — perception, mouvement, défense, élément, physiologie, pouvoir mental — et le MJ choisit une Miette cohérente dans cette famille. Pas de sélection d’un Talent précis à la carte.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Récolter les miettes","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_autel-affame', 'Autel affamé', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel prolongé, Souillure 21 ; requiert Partage de l''Écume","activation":null,"texte_court":"un Autel intact et non purifié garde une Miette inutilisée jusqu''à la fin du scénario. Un initié qui a Récolter les miettes l''absorbe au contact pour 2 PA.","texte_reference":"Autel affaméProfil: 3 PTV • RITE • R • Rituel prolongé • Prérequis : Partage de l’Écume • Souillure 21Un Autel peut conserver une Miette inutilisée jusqu’à la fin du scénario tant qu’il reste intact et non purifié. Un initié avec Récolter les miettes peut l’absorber en 2 PA au contact.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Partage de l’Écume","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_la_loge_d_ecume_la_digestion', 'La Digestion', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_digestion-lente', 'Digestion lente', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, passif, Souillure 15","activation":null,"texte_court":"une Miette dure jusqu''à la fin du scénario au lieu du prochain repos prolongé. Souillure la première fois que cette prolongation produit son effet dans le scénario.","texte_reference":"Digestion lenteProfil: 1 PTV • RITE • SR/R • Passif • Souillure 15Une Miette portée peut survivre jusqu’à la fin du scénario au lieu du prochain repos prolongé. Le Test de Souillure est effectué la première fois que cette prolongation produit réellement son effet dans le scénario.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_deuxieme-estomac', 'Deuxième estomac', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, passif, Souillure 18 ; requiert Digestion lente","activation":null,"texte_court":"tu portes deux Miettes de victimes distinctes. Deux propriétés équivalentes ne se cumulent pas.","texte_reference":"Deuxième estomacProfil: 2 PTV • RITE • R • Passif • Prérequis : Digestion lente • Souillure 18Le cultiste peut porter deux Miettes actives issues de victimes distinctes. Deux propriétés équivalentes ne se cumulent pas.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Digestion lente","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_regurgiter-le-don', 'Régurgiter le Don', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA, 1/scène, Souillure 18","activation":null,"texte_court":"tu détruis une Miette pour en projeter le principe (protection brève, perception unique, mouvement simple, petit effet cohérent). Jamais plus fort que la Miette ; elle est perdue.","texte_reference":"Régurgiter le DonProfil: 2 PTV • RITE • R • 1 PA • 1/Scène • Souillure 18Le cultiste détruit une Miette pour projeter temporairement son principe : protection brève, perception unique, mouvement simple ou petit effet cohérent. Jamais plus puissant que la Miette portée ; après usage elle est perdue.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_assimilation-interdite', 'Assimilation interdite', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel, 1/scénario, Souillure 21 ; requiert Deuxième estomac","activation":null,"texte_court":"une Miette est inscrite dans ta Vérité jusqu''à la fin du scénario, même si son support disparaît. +1 Corruption Vhodhal automatique.","texte_reference":"Assimilation interditeProfil: 3 PTV • RITE • R • Rituel • 1/Scénario • Prérequis : Deuxième estomac • Souillure 21Le cultiste inscrit une Miette profondément dans sa Vérité afin de la maintenir jusqu’à la fin du scénario même si son support normal disparaîtrait. En plus de la Souillure 21, il gagne automatiquement +1 Corruption Vhodhal.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Deuxième estomac","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_la_loge_d_ecume_les_porteurs', 'Les Porteurs', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"« Rite du Porteur requis » se lit ainsi : le Rite du Porteur est la scène d''initiation par laquelle la Loge installe le vecteur. Ce n''est pas un talent à acheter. Correction de lecture, sans coût."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_porteur-sain', 'Porteur sain', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"FAVEUR, SR/R, passif, Souillure 15","activation":null,"texte_court":"la Famine est installée en toi comme vecteur extérieur, sans Corruption automatique et sans aucun Don de Famine. Elle ouvre seulement les techniques des Porteurs. Une vraie purification du lien la supprime.","texte_reference":"Porteur sainProfil: 1 PTV • FAVEUR • SR/R • Passif • Rite du Porteur requis • Souillure 15La Famine est installée comme vecteur extérieur sans Corruption automatique. Le personnage ne gagne aucun Don de Famine. La Faveur permet seulement les techniques qui utilisent ce vecteur ; elle peut être supprimée par une vraie purification du lien.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"FAVEUR","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_toucher-contaminant', 'Toucher contaminant', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1/scène, Souillure 18 ; requiert Porteur sain","activation":null,"texte_court":"après un contact physique prolongé ou une blessure que tu infliges, tu exposes la cible : Vigueur + Constitution contre 15 ; échec +1 Corruption, échec narratif +2. Une tentative par cible et par scène.","texte_reference":"Toucher contaminantProfil: 2 PTV • FAVEUR • R • 1/Scène • Prérequis : Porteur sain • Souillure 18Après contact physique prolongé ou blessure directement infligée, exposer volontairement la cible : Vigueur + Constitution difficulté 15 ; échec +1 Corruption, échec narratif +2. Une tentative par cible et par scène.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"FAVEUR","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Porteur sain","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_ecume-du-porteur', 'Écume du Porteur', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1 PA, Souillure 18 ; requiert Porteur sain","activation":null,"texte_court":"tu produis un peu d''Écume Blanche (contaminant, composant rituel, marque d''Autel). Ingérée ou mise dans une blessure, elle permet Toucher contaminant sans contact prolongé.","texte_reference":"Écume du PorteurProfil: 2 PTV • FAVEUR • R • 1 PA • Prérequis : Porteur sain • Souillure 18Le cultiste produit une petite quantité d’Écume Blanche utilisable comme contaminant, composant rituel ou marque d’Autel. Ingérée ou introduite dans une blessure, elle permet Toucher contaminant sans contact prolongé.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"FAVEUR","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Porteur sain","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_contenir-la-faim', 'Contenir la Faim', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, SR/R, Réaction 1 PA, 1/scène, Souillure 21","activation":null,"texte_court":"quand un Corrompu proche entre en Crise Blanche, Volonté + Maîtrise spirituelle contre les siennes. En réussite, son obligation de consacrer 1 PA à la faim est suspendue jusqu''à la fin de sa prochaine activation.","texte_reference":"Contenir la FaimProfil: 3 PTV • RITE • SR/R • Réaction 1 PA • 1/Scène • Souillure 21Lorsqu’un Corrompu proche entre en Crise Blanche, Volonté + Maîtrise spirituelle du cultiste contre Volonté + Maîtrise spirituelle du Corrompu. En réussite, l’obligation de consacrer 1 PA à la faim est suspendue jusqu’à la fin de la prochaine activation du Corrompu.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_la_loge_d_ecume_le_mageius_devore', 'Le Mageius dévoré', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"« Mage uniquement » est précisé en **prêtre Mage**, puisque l''Affinité rejoint sa Roue. La victime est toujours un Mage. Correction de lecture."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_gouter-le-mageius', 'Goûter le Mageius', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18 ; prêtre Mage","activation":null,"texte_court":"quand un Mage est sacrifié sur l''Autel, tu perçois les Domaines et Affinités majeures de son Mageius et tu en choisis une comme cible des rites suivants.","texte_reference":"Goûter le MageiusProfil: 2 PTV • RITE • R • Rituel • Mage uniquement • Souillure 18Lorsqu’un Mage est sacrifié sur l’Autel, le prêtre perçoit les Domaines/Affinités majeures contenus dans son Mageius et peut en choisir une comme cible des rites suivants.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_affinite-devoree', 'Affinité dévorée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18 ; requiert Goûter le Mageius","activation":null,"texte_court":"tu absorbes cette Affinité jusqu''à la fin du scénario. Elle compte comme disponible pour ta Roue, sans Compétence, savoir ni Talent magique.","texte_reference":"Affinité dévoréeProfil: 2 PTV • RITE • R • Rituel • Prérequis : Goûter le Mageius • Souillure 18Le prêtre absorbe temporairement une Affinité du Mageius sacrifié jusqu’à la fin du scénario. Elle compte comme disponible pour sa Roue, mais ne donne ni Compétence, ni savoir, ni Talent magique.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Goûter le Mageius","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhodhal_loge-d-ecume_devorer-le-mageius', 'Dévorer le Mageius', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel exceptionnel, 1/scénario, Souillure 21 ; requiert Affinité dévorée","activation":null,"texte_court":"l''Affinité volée devient une Empreinte étrangère durable de ton Mageius (une seule par PJ). +1 Corruption Vhodhal automatique.","texte_reference":"Dévorer le MageiusProfil: 3 PTV • RITE • R • Rituel exceptionnel • 1/Scénario • Prérequis : Affinité dévorée • Souillure 21Une Affinité volée devient une Empreinte étrangère durable du Mageius. Maximum une Empreinte chez un PJ. En plus de la Souillure 21, le rite donne automatiquement +1 Corruption Vhodhal.","lore":null,"groupe_actuel":"Vhodhal — Loge d’Écume","kind":"RITE","profondeur":null,"source":"vhodhal","famille":"Loge d’Écume","prerequis_texte":"Affinité dévorée","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
