INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'corruption', 'corruption_v_aagor_la_sombre_verite', 'V''Aagor — la Sombre-Vérité', NULL, '{"nature":"corruption","chemin":["V''Aagor — la Sombre-Vérité"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_sombre_verite_l_annexe', 'L''Annexe', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_annexe-sombre', 'Annexe sombre', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"au contact, un objet ou une portion de matière non vivante devient ton Annexe jusqu''à la fin de la scène. Tu sais si elle existe encore, si elle est déplacée ou détruite, et sa direction générale à l''échelle locale. Une Annexe à la fois.","texte_reference":"Annexe sombreProfil: 1 PTV • DON • Marqué • SR/R • 1 PAAu contact d’un objet ou d’une portion de matière non vivante de taille raisonnable, le porteur en fait son Annexe jusqu’à la fin de la scène. Il sait si elle existe encore, si elle est fortement déplacée/détruite et sa direction générale à échelle locale. Une Annexe par défaut.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Marqué","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_voir-par-ce-qui-est-mien', 'Voir par ce qui est mien', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, SR/R, 1 PA ; requiert Annexe sombre","activation":null,"texte_court":"pendant un round, tu vois et entends depuis ton Annexe. Aucun sens en plus ; tes sens ordinaires sont fortement atténués.","texte_reference":"Voir par ce qui est mienProfil: 2 PTV • DON • Envahi • SR/R • 1 PA • Prérequis : Annexe sombrePendant un round, le porteur perçoit depuis son Annexe comme si ses yeux et oreilles se trouvaient là. Il n’obtient aucun sens supplémentaire et ses perceptions physiques ordinaires sont fortement atténuées pendant l’utilisation.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Envahi","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":"Annexe sombre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_corps-annexe', 'Corps-annexe', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA ; requiert Annexe sombre","activation":null,"texte_court":"une Annexe non vivante tenue à une ou deux mains se fond dans ton corps, inaccessible. La ressortir coûte 1 PA. Une seule ; pas une poche infinie.","texte_reference":"Corps-annexeProfil: 2 PTV • DON • Envahi • R • 1 PA • Prérequis : Annexe sombreUne Annexe non vivante portée à une ou deux mains peut se fondre dans le corps et devenir matériellement inaccessible. La ressortir coûte 1 PA. Une seule à la fois ; ce n’est pas une poche dimensionnelle infinie.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Envahi","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":"Annexe sombre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_rejoindre-ce-qui-est-mien', 'Rejoindre ce qui est mien', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, 2 PA, 1/scène ; requiert Annexe sombre","activation":null,"texte_court":"tu t''infiltres dans une surface assez grande et ressors par ton Annexe, à courte portée, dans le même plan. Scellements, frontières et dispositifs anti-intrusion peuvent bloquer.","texte_reference":"Rejoindre ce qui est mienProfil: 3 PTV • DON • Envahi • R • 2 PA • 1/Scène • Prérequis : Annexe sombreLe porteur s’infiltre dans une surface suffisamment importante et ressort instantanément par son Annexe à courte portée dans le même plan. Scellements, frontières dimensionnelles et dispositifs explicitement anti-intrusion peuvent bloquer.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Envahi","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":"Annexe sombre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_agir-par-l-annexe', 'Agir par l''Annexe', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 2 PA, 1/scène","activation":null,"texte_court":"une partie de ton corps se manifeste quelques secondes depuis ton Annexe pour une action physique simple (saisir, pousser, ouvrir, couper, attaquer au contact). Les 2 PA sont l''action.","texte_reference":"Agir par l’AnnexeProfil: 3 PTV • DON • Au bord • R • 2 PA • 1/ScèneLe porteur manifeste quelques secondes une partie de son corps depuis son Annexe et effectue une seule action physique simple : saisir, pousser, déposer, ouvrir, couper ou attaquer au contact. Les 2 PA sont l’action ; aucune activation supplémentaire.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Au bord de la Rupture","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_tout-est-deja-moi', 'Tout est déjà moi', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 2 PA, 1/scène","activation":null,"texte_court":"pendant un round, toute matière non vivante que tu touches compte comme Annexe pour les Dons compatibles. Le contact rompu, elle cesse ; le sol ne fait pas de la planète une Annexe.","texte_reference":"Tout est déjà moiProfil: 3 PTV • DON • Au bord • R • 2 PA • 1/ScènePendant un round, toute matière non vivante directement touchée peut être traitée comme Annexe supplémentaire pour les Dons compatibles. La continuité est locale et cesse avec le contact ; toucher le sol ne transforme pas la planète en Annexe.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Au bord de la Rupture","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_fragment-de-secours', 'Fragment de secours', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction, 1/scénario","activation":null,"texte_court":"au seuil de Mort, ton essence passe dans une Annexe locale ; le corps tombe inerte. Si l''Annexe survit et le corps reste récupérable, tu reviens en fin de scène à 0 PV, Stabilisé. +1 Corruption V''Aagor automatique.","texte_reference":"Fragment de secoursProfil: 3 PTV • DON • Au bord • R • Réaction • 1/ScénarioLorsqu’il devrait franchir le seuil de Mort, le porteur projette son essence dans une Annexe locale. Le corps tombe inerte. Si l’Annexe survit et le corps reste récupérable, l’essence revient à la fin de la scène à 0 PV Stabilisé. +1 Corruption V’Aagor automatique.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Au bord de la Rupture","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_sombre_verite_l_ombre', 'L''Ombre', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_ombre-qui-deborde', 'Ombre qui déborde', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"ton ombre fait une manipulation simple à quelques mètres (prendre, tirer, pousser, actionner), avec tes PA. Aucune attaque gratuite, aucun travail technique précis.","texte_reference":"Ombre qui débordeProfil: 1 PTV • DON • Marqué • SR/R • 1 PALa propre ombre accomplit une manipulation simple à quelques mètres : prendre, tirer, pousser, actionner. Elle utilise toujours les PA du personnage, n’effectue aucune attaque gratuite et ne réalise pas de travail technique précis.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Marqué","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_ombre-docile', 'Ombre docile', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"tu étends, contractes ou déformes ton ombre sur quelques mètres, quel que soit l''éclairage. Elle contourne un petit obstacle ou rejoint une autre ombre visible, sans produire de force.","texte_reference":"Ombre docileProfil: 1 PTV • DON • Marqué • SR/R • 1 PALe porteur étend, contracte ou déforme sa propre ombre sur quelques mètres même si l’éclairage réel ne produirait pas cette forme. Elle peut contourner un petit obstacle ou rejoindre une autre zone d’ombre visible, sans produire de force.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Marqué","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_se-fondre-dans-le-noir', 'Se fondre dans le noir', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA ; requiert Ombre docile","activation":null,"texte_court":"dans une ombre assez grande, tu te fonds visuellement en elle. Thermique, son, odeur, contact et perceptions surnaturelles ne sont pas trompés d''office. Déplacement lent possible dans une ombre continue.","texte_reference":"Se fondre dans le noirProfil: 2 PTV • DON • Envahi • R • 1 PA • Prérequis : Ombre docileDans une zone d’ombre assez grande pour contenir son corps, le porteur fusionne visuellement avec elle. Il reste physiquement présent ; thermique, son, odeur, contact et perceptions surnaturelles ne sont pas trompés automatiquement. Un déplacement lent dans une ombre continue reste possible.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Envahi","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":"Ombre docile","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_ombre-solide', 'Ombre solide', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA ; requiert Ombre docile","activation":null,"texte_court":"une portion de ton ombre devient consistante jusqu''au début de ta prochaine activation (barre, prise, écran, plateforme, crochet, entrave simple). Ni attaque ni PA gratuits ; une entrave demande une opposition.","texte_reference":"Ombre solideProfil: 2 PTV • DON • Envahi • R • 1 PA • Prérequis : Ombre docileUne portion de la propre ombre devient consistante jusqu’au début de la prochaine activation : barre, prise, écran, plateforme, crochet ou entrave simple. Elle ne crée ni attaque ni PA gratuits ; une entrave demande une opposition appropriée.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Envahi","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":"Ombre docile","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_ombre-dans-l-ombre', 'Ombre dans l''ombre', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA","activation":null,"texte_court":"ton ombre rejoint celle d''une créature ; si elle refuse, Volonté + Maîtrise spirituelle contre sa Défense occulte. En réussite, un filament la suit pour la scène : direction générale, et perception par Voir par ce qui est mien à portée locale. Ne révèle pas sa forme V.","texte_reference":"Ombre dans l’ombreProfil: 2 PTV • DON • Envahi • R • 1 PALa propre ombre rejoint celle d’une créature. Si elle refuse : Volonté + Maîtrise spirituelle contre Défense occulte. En réussite, un filament accompagne sa silhouette pour la scène ; direction générale et perception via Voir par ce qui est mien restent possibles à portée locale. Ne révèle pas sa forme V.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Envahi","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_noyer-la-silhouette', 'Noyer la silhouette', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 2 PA, 1/scène ; requiert Ombre docile","activation":null,"texte_court":"jusqu''au début de ta prochaine activation, les ombres d''une petite zone se joignent à la tienne ; tout point de cette nappe prolonge tes Dons d''Ombre. Jamais un bâtiment entier par défaut.","texte_reference":"Noyer la silhouetteProfil: 3 PTV • DON • Au bord • R • 2 PA • 1/Scène • Prérequis : Ombre docileJusqu’au début de la prochaine activation, les ombres d’une petite zone deviennent continues avec la sienne. Tout point de cette nappe peut servir de prolongement immédiat pour ses Dons d’Ombre. La zone reste locale, jamais un bâtiment entier par défaut.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Au bord de la Rupture","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":"Ombre docile","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_sombre_verite_la_matiere_unie', 'La matière unie', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Poids impossible ressemble à Masse empruntée (Œil Blanc) : on garde les deux (A4). Ici c''est un Don sans Souillure, qui demande la profondeur ; là, une Faveur à 2 PTV qui coûte une Souillure à chaque usage."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_poids-impossible', 'Poids impossible', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, R, 1 PA","activation":null,"texte_court":"jusqu''au début de ta prochaine activation, Quasi-ombre (masse presque nulle) ou Abîme (impossible à déplacer par une force humaine ordinaire). Ni vol, ni bonus de DGT ; le support peut céder.","texte_reference":"Poids impossibleProfil: 2 PTV • DON • Marqué • R • 1 PAJusqu’au début de la prochaine activation : Quasi-ombre réduit presque à néant la masse du corps, ou Abîme le rend extrêmement difficile à déplacer par une force humaine ordinaire. Pas de vol, pas de bonus de DGT ; le support peut céder.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Marqué","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"correction","changements":"aucun. Poids impossible ressemble à Masse empruntée (Œil Blanc) : on garde les deux (A4). Ici c''est un Don sans Souillure, qui demande la profondeur ; là, une Faveur à 2 PTV qui coûte une Souillure à chaque usage."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_peau-sans-frontiere', 'Peau sans frontière', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, R, Réaction 1 PA, 1/round","activation":null,"texte_court":"après une attaque physique réussie, ta matière coule autour d''un transpercement, d''un agrippement, d''un empalement ou d''une immobilisation locale. Tous les dégâts restent, mais une Altération physique cohérente est annulée.","texte_reference":"Peau sans frontièreProfil: 2 PTV • DON • Marqué • R • Réaction 1 PA • 1/roundAprès une attaque physique réussie, le porteur laisse sa matière couler autour d’un effet de transpercement, agrippement, empalement ou immobilisation locale. Les dégâts s’appliquent intégralement, mais une Altération physique cohérente peut être annulée.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Marqué","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_faire-un', 'Faire Un', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA","activation":null,"texte_court":"deux objets ou matières non vivants adjacents deviennent une seule continuité jusqu''à la fin de la scène (porte soudée, chaîne au mur, arme réunie). Les matériaux gardent leur qualité ; le plus faible peut rompre.","texte_reference":"Faire UnProfil: 2 PTV • DON • Envahi • R • 1 PADeux objets ou portions de matière non vivante directement adjacents deviennent une seule continuité jusqu’à la fin de la scène : porte soudée à son bâti, chaîne au mur, arme cassée réunie. Les matériaux gardent leur qualité ; le plus faible peut toujours rompre.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Envahi","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_fusion-intrusive', 'Fusion intrusive', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA, 1/scène","activation":null,"texte_court":"attaque de contact Vigueur + Pugilat contre Défense, sans DGT. En réussite, une partie de la cible est fusionnée à un élément adjacent. Se libérer : 1 PA et Vigueur + Athlétisme contre 18, ou un moyen adapté.","texte_reference":"Fusion intrusiveProfil: 3 PTV • DON • Envahi • R • 1 PA • 1/ScèneAttaque de contact Vigueur + Pugilat contre Défense, sans DGT. En réussite, une partie physique de la cible est fusionnée à un élément adjacent. Pour se libérer : 1 PA + Vigueur + Athlétisme difficulté 18, ou moyen surnaturel/matériel adapté.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Envahi","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_sombre-verite_approprier-l-agression', 'Approprier l''agression', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"après avoir résisté à un Talent surnaturel actif qui te visait, tu gardes le lien. Avant la fin de ta prochaine activation, 1 PA renvoie le même effet, avec son résultat d''origine, vers sa source si elle est une cible valide. Rien n''est copié.","texte_reference":"Approprier l’agressionProfil: 3 PTV • DON • Au bord • R • Réaction 1 PA • 1/ScèneAprès avoir résisté à un Talent surnaturel Actif qui le ciblait directement, le porteur conserve le lien par lequel l’effet l’a atteint. Avant la fin de sa prochaine activation, 1 PA peut renvoyer le même effet vers sa source avec son résultat d’origine si la source est une cible valide. Aucun Talent n’est copié.","lore":null,"groupe_actuel":"V’Aagor — Sombre-Vérité","kind":"DON","profondeur":"Au bord de la Rupture","source":"vaagor","famille":"Sombre-Vérité","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'corruption', 'corruption_culte_le_deimonisme', 'Culte — le Deimonisme', NULL, '{"nature":"corruption","chemin":["V''Aagor — la Sombre-Vérité","Culte — le Deimonisme"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_le_deimonisme_connaitre_l_ombre', 'Connaître l''Ombre', NULL, '{"nature":"corruption","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_sentir-les-ombres', 'Sentir les Ombres', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, passif, Souillure 15","activation":null,"texte_court":"tu perçois à courte portée un Deimon ou un être surtout fait d''Ombre, même caché aux sens ordinaires. Ni espèce, ni nom, ni intention, ni position exacte à travers plusieurs murs.","texte_reference":"Sentir les OmbresProfil: 1 PTV • RITE • SR/R • Passif • Souillure 15Percevoir à courte portée la présence d’un Deimon ou être principalement constitué d’Ombre surnaturelle, même caché aux sens ordinaires. Pas d’espèce exacte, nom, intention ni localisation parfaite à travers plusieurs murs.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_lire-le-noyau', 'Lire le noyau', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1 PA, Souillure 18","activation":null,"texte_court":"sur un Deimon perçu, tu identifies ce qui maintient sa volonté (âme, émotion, résidu magique, pacte, fragment…). Pas toute sa fiche.","texte_reference":"Lire le noyauProfil: 2 PTV • RITE • SR/R • 1 PA • Souillure 18Sur un Deimon directement perçu, identifier le principe qui maintient sa volonté : âme, émotion, résidu magique, pacte, fragment ou autre noyau. Ne révèle pas toute sa fiche.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_nom-dans-la-nuit', 'Nom dans la nuit', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 21","activation":null,"texte_court":"une fois obtenu le vrai nom ou la signature d''un Deimon, tu le gardes comme ancrage pour l''invoquer, le chercher par rituel et le distinguer d''un autre.","texte_reference":"Nom dans la nuitProfil: 3 PTV • RITE • SR/R • Rituel • Souillure 21Après avoir obtenu le véritable nom, désignation profonde ou signature individuelle d’un Deimon, le conserver comme ancrage pour Invocation, recherche rituelle et distinction certaine entre deux entités semblables.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_le_deimonisme_l_appel', 'L''Appel', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_appeler-par-le-nom', 'Appeler par le nom', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 18 ; requiert Nom dans la nuit","activation":null,"texte_court":"tu ouvres un appel vers un Deimon nommé dans l''Ombre-Monde. Il l''entend et peut venir de lui-même ; aucun contrôle.","texte_reference":"Appeler par le nomProfil: 2 PTV • RITE • SR/R • Rituel • Prérequis : Nom dans la nuit • Souillure 18Ouvrir un appel vers un Deimon nommé situé dans l’Ombre-Monde. Il entend l’appel et peut rejoindre volontairement le rite ; aucun contrôle n’est imposé.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":"Nom dans la nuit","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_arracher-a-l-ombre', 'Arracher à l''Ombre', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18 ; requiert Appeler par le nom","activation":null,"texte_court":"Volonté + Maîtrise spirituelle contre sa Défense occulte. En réussite, il est forcé de se manifester dans la zone rituelle, ni allié ni contrôlé. Un échec narratif peut retourner l''ouverture contre toi.","texte_reference":"Arracher à l’OmbreProfil: 2 PTV • RITE • R • Rituel • Prérequis : Appeler par le nom • Souillure 18Volonté + Maîtrise spirituelle contre Défense occulte du Deimon. En réussite, il est forcé de se manifester dans la zone rituelle, sans devenir allié ni contrôlé. Un échec narratif peut retourner l’ouverture contre l’invocateur.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":"Appeler par le nom","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_ancrage-de-manifestation', 'Ancrage de manifestation', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA par round ou rituel, Souillure 18","activation":null,"texte_court":"tu maintiens un Deimon manifesté malgré le rejet naturel, l''Hologramme ou l''instabilité. Souillure à l''activation seulement.","texte_reference":"Ancrage de manifestationProfil: 2 PTV • RITE • R • 1 PA/round ou rituel • Souillure 18Maintenir un Deimon manifesté malgré rejet naturel, Hologramme ou instabilité. Le Test de Souillure se fait à l’activation initiale, pas à chaque PA de maintien.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_le_deimonisme_corrompre_l_ombre', 'Corrompre l''Ombre', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Prendre les rênes (2 PTV) demande Ombre appropriée (3 PTV). Ce prérequis plus cher est **gardé** : il est écrit à l''origine et freine le contrôle."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_souillure-d-ombre', 'Souillure d''Ombre', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA, Souillure 15","activation":null,"texte_court":"au contact ou par un lien valide, Volonté + Maîtrise spirituelle contre la Défense occulte du Deimon. En réussite, 1 Marque aagorienne jusqu''à la fin de la scène. Elle ouvre les techniques suivantes ; elle ne contrôle pas.","texte_reference":"Souillure d’OmbreProfil: 1 PTV • RITE • R • 1 PA • Souillure 15Au contact ou via un lien valide : Volonté + Maîtrise spirituelle contre Défense occulte du Deimon. En réussite, imposer 1 Marque aagorienne jusqu’à la fin de la scène. La Marque ouvre les techniques suivantes mais ne contrôle pas la volonté.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_habiter-l-ombre', 'Habiter l''Ombre', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA, 1/scène, Souillure 18","activation":null,"texte_court":"ta conscience passe dans un Deimon corrompu perçu ou lié jusqu''au début de ta prochaine activation. Ton corps reste immobile ; le Deimon sait qu''on l''utilise. Pas d''accès à ses pensées privées.","texte_reference":"Habiter l’OmbreProfil: 2 PTV • RITE • R • 2 PA • 1/Scène • Souillure 18Projeter sa conscience dans un Deimon corrompu perçu ou lié jusqu’au début de la prochaine activation. Le corps réel reste immobile ; le Deimon est conscient d’être utilisé. Pas d’accès automatique à ses pensées privées.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_chimere-d-ombres', 'Chimère d''Ombres', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, 1/scénario, Souillure 18","activation":null,"texte_court":"deux Deimons structurellement corrompus et compatibles fusionnent en une manifestation : deux volontés, une seule économie d''action. Profil combiné avec le MJ ; souvent instable.","texte_reference":"Chimère d’OmbresProfil: 2 PTV • RITE • R • Rituel • 1/Scénario • Souillure 18Fusionner deux Deimons structurellement corrompus et compatibles dans une seule manifestation. Ils gardent deux volontés mais une seule économie d’action. Profil combiné défini avec le MJ ; instabilité fréquente.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_enfoncer-la-tenebre', 'Enfoncer la ténèbre', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 21 ; requiert Souillure d''Ombre","activation":null,"texte_court":"sur un Deimon captif, volontaire, lié, vaincu ou durablement accessible, la Marque devient Corruption structurelle par opposition prolongée. Il devient aagorien, pas loyal.","texte_reference":"Enfoncer la ténèbreProfil: 3 PTV • RITE • R • Rituel • Prérequis : Souillure d’Ombre • Souillure 21Sur un Deimon captif, volontaire, lié, vaincu ou durablement accessible, transformer la Marque en Corruption structurelle de V’Aagor par opposition prolongée. Le Deimon devient réellement aagorien, mais pas automatiquement loyal.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":"Souillure d’Ombre","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_ombre-appropriee', 'Ombre appropriée', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, passif, Souillure 21 ; requiert Enfoncer la ténèbre","activation":null,"texte_court":"un Deimon que tu as corrompu compte comme Annexe vivante pour la direction, la perception et certains liens. Jamais de Corps-annexe ni de fusion matérielle.","texte_reference":"Ombre appropriéeProfil: 3 PTV • RITE • R • Passif • Prérequis : Enfoncer la ténèbre • Souillure 21Un Deimon structurellement corrompu par le personnage compte comme Annexe vivante spéciale pour direction, perception et certains liens. Jamais de Corps-annexe ni fusion matérielle automatique.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":"Enfoncer la ténèbre","statut_regle":"correction","changements":"Prendre les rênes (2 PTV) demande Ombre appropriée (3 PTV). Ce prérequis plus cher est **gardé** : il est écrit à l''origine et freine le contrôle."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_prendre-les-renes', 'Prendre les rênes', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA, 1/round, Souillure 18 ; requiert Ombre appropriée","activation":null,"texte_court":"Volonté + Maîtrise spirituelle contre la Défense occulte d''un Deimon que tu as corrompu. En réussite, il fait une action simple à sa prochaine occasion. Le PA est le tien ; pas d''armée gratuite.","texte_reference":"Prendre les rênesProfil: 2 PTV • RITE • R • 1 PA • 1/round • Prérequis : Ombre appropriée • Souillure 18Volonté + Maîtrise spirituelle contre Défense occulte d’un Deimon structurellement corrompu par le personnage. En réussite, lui imposer une action simple à sa prochaine occasion. Le PA payé est celui du Deimoniste ; pas d’armée gratuite.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":"Ombre appropriée","statut_regle":"correction","changements":"Prendre les rênes (2 PTV) demande Ombre appropriée (3 PTV). Ce prérequis plus cher est **gardé** : il est écrit à l''origine et freine le contrôle."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_deimonisme_engendrer-l-ombre', 'Engendrer l''Ombre', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel interdit, Souillure 21","activation":null,"texte_court":"tu détruis une âme, une essence magique ou un noyau surnaturel riche et bâtis la Sombre-Vérité autour du résidu. Un Deimon naît ; le MJ fixe sa puissance et sa personnalité. Il ne t''appartient pas.","texte_reference":"Engendrer l’OmbreProfil: 3 PTV • RITE • R • Rituel interdit • Souillure 21Détruire une âme, essence magique ou noyau surnaturel assez riche puis assembler la Sombre-Vérité autour du résidu. Un nouveau Deimon naît ; le MJ crée puissance et personnalité. Il n’appartient pas automatiquement au créateur.","lore":null,"groupe_actuel":"V’Aagor — Deimonisme","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Deimonisme","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
