INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_l_ordre_de_longinus_la_communion', 'La Communion', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_communion-noire', 'Communion noire', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 15","activation":null,"texte_court":"jusqu''à 3 consentants entrent dans la Communion pour la scène. Chacun sait seulement qui appartient encore au Corps, et si l''un vient de mourir ou de partir. Ni télépathie ni localisation.","texte_reference":"Communion noireProfil: 1 PTV • RITE • SR/R • Rituel • Souillure 15Intégrer jusqu’à 3 personnes consentantes dans une Communion pour la scène. Les membres savent seulement qui appartient encore au Corps et si l’un vient de mourir ou quitter le lien. Pas de télépathie ni localisation.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_un-seul-corps', 'Un seul Corps', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, Réaction 1 PA, 1/round, Souillure 18","activation":null,"texte_court":"quand un Communiant perçu devrait subir une Altération surnaturelle du corps ou de l''essence, tu résistes à sa place. En réussite, elle est annulée ; en échec, elle s''applique et tu subis 1 PV surnaturel irréductible.","texte_reference":"Un seul CorpsProfil: 2 PTV • RITE • SR/R • Réaction 1 PA • 1/round • Souillure 18Lorsqu’un Communiant perçu devrait subir une Altération surnaturelle imposée au corps ou à l’essence, le Longinus peut effectuer lui-même la résistance. En réussite l’Altération est annulée ; en échec elle s’applique et le Longinus subit 1 PV surnaturel irréductible.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_ce-qui-frappe-l-un-frappe-tous', 'Ce qui frappe l''un frappe tous', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, Réaction 1 PA, 1/scène, Souillure 18","activation":null,"texte_court":"quand un Communiant subit une attaque surnaturelle directe d''une source perçue, tous reconnaissent cette source comme agresseur jusqu''à la fin de ta prochaine activation. Ni Nature, ni position, ni faiblesse.","texte_reference":"Ce qui frappe l’un frappe tousProfil: 2 PTV • RITE • SR/R • Réaction 1 PA • 1/Scène • Souillure 18Lorsqu’un Communiant subit une attaque surnaturelle directe d’une source perçue, tous les Communiants savent reconnaître cette source comme agresseur du Corps jusqu’à la fin de la prochaine activation du Longinus. Pas de Nature, position ou faiblesse révélée.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_rien-ne-sort-du-corps', 'Rien ne sort du Corps', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, Réaction 1 PA, 1/scène, Souillure 21","activation":null,"texte_court":"quand un Communiant consentant devrait être possédé, expulsé spirituellement, arraché à son plan ou devenir réceptacle, Volonté + Maîtrise spirituelle contre la Puissance. En réussite, l''effet échoue sur lui.","texte_reference":"Rien ne sort du CorpsProfil: 3 PTV • RITE • R • Réaction 1 PA • 1/Scène • Souillure 21Lorsqu’un Communiant consentant devrait être possédé, expulsé spirituellement, arraché à son plan ou transformé en réceptacle externe : Volonté + Maîtrise spirituelle contre Puissance. En réussite, cet effet échoue sur lui.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_l_ordre_de_longinus_la_liturgie_inversee', 'La Liturgie inversée', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Faux sacrement prête un RITE Longinus au lieu d''une FAVEUR, que l''Ordre n''a pas (question 2, validée le 30/10)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_liturgie-inversee', 'Liturgie inversée', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 15","activation":null,"texte_court":"tu profanes un autel, un symbole, une huile, un encens, une relique ou une petite zone jusqu''à la fin de la scène. Le Profané Longinus sert de support aux Rites ; il n''est jamais Sacré.","texte_reference":"Liturgie inverséeProfil: 1 PTV • RITE • SR/R • Rituel • Souillure 15Profaner un autel, symbole, huile, encens, relique ou petite zone jusqu’à la fin de la scène. Profané Longinus sert de support aux Rites mais n’est jamais Sacré.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_faux-sacrement', 'Faux sacrement', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1/scène, Souillure 18","activation":null,"texte_court":"un Communiant volontaire reçoit pour la scène un **RITE** Longinus que tu possèdes et dont il remplit les autres conditions. Il n''acquiert ni Source ni compatibilité ; il teste la Souillure du Rite à chaque activation.","texte_reference":"Faux sacrementProfil: 2 PTV • RITE • SR/R • 1/Scène • Souillure 18Un Communiant volontaire reçoit pour la scène un Talent Longinus marqué FAVEUR que le prêtre possède et dont il remplit les autres conditions. Le bénéficiaire n’acquiert pas automatiquement une Source ou une compatibilité absente.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"correction","changements":"Faux sacrement prête un RITE Longinus au lieu d''une FAVEUR, que l''Ordre n''a pas (question 2, validée le 30/10)."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_absoudre-dans-l-ombre', 'Absoudre dans l''Ombre', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, 2 PA, 1/scène, Souillure 18","activation":null,"texte_court":"sur un Communiant volontaire, Volonté + Maîtrise spirituelle contre une Marque, une malédiction ou un lien extérieur identifié. En réussite, l''effet cesse d''agir jusqu''à la fin de la scène, sans être détruit.","texte_reference":"Absoudre dans l’OmbreProfil: 2 PTV • RITE • SR/R • 2 PA • 1/Scène • Souillure 18Sur un Communiant volontaire : Volonté + Maîtrise spirituelle contre une Marque, malédiction ou lien extérieur identifié. En réussite, l’effet cesse d’agir jusqu’à la fin de la scène mais n’est pas détruit ; il revient ensuite s’il n’a pas été réellement purifié.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_hostie-de-sombre-verite', 'Hostie de Sombre-Vérité', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, préparation, Souillure 18","activation":null,"texte_court":"tu prépares une dose stabilisée de Sombre-Vérité. Ingérée de plein gré, elle rend Communiant et peut maintenir SR contre une correction ordinaire de l''Hologramme pour la scène. Ne brise ni HDS ni Holojamer.","texte_reference":"Hostie de Sombre-VéritéProfil: 2 PTV • RITE • R • Préparation • Souillure 18Préparer une dose matérielle de Sombre-Vérité stabilisée. Ingérée volontairement, elle rend immédiatement Communiant et peut maintenir SR contre une correction ordinaire de l’Hologramme pour la scène. Ne brise pas HDS/Holojamer explicite.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_eglise-sans-lumiere', 'Église sans lumière', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA puis 1 PA par round, Souillure 21","activation":null,"texte_court":"dans une petite zone Profanée, les Communiants se perçoivent entre eux et les Rites Longinus n''ont plus besoin de ligne de vue entre eux. Une perception de lumière ou de divinité extérieure doit vaincre ta Volonté + Maîtrise spirituelle pour sonder la zone.","texte_reference":"Église sans lumièreProfil: 3 PTV • RITE • R • 2 PA + maintien 1 PA/round • Souillure 21Dans une petite zone Profanée Longinus, les Communiants se perçoivent normalement entre eux et les Rites Longinus ne nécessitent plus de ligne visuelle entre eux. Une perception surnaturelle de lumière/divinité extérieure doit vaincre Volonté + Maîtrise spirituelle du prêtre pour sonder la zone.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_messe-de-l-indivisible', 'Messe de l''Indivisible', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel prolongé, 1/scénario, Souillure 21","activation":null,"texte_court":"jusqu''à 7 Communiants offrent chacun une capacité Longinus ou Sombre-Vérité. Pour la scène préparée, chacune peut servir une fois à un autre Communiant, à son coût normal. Tous les prérequis restent dus ; un RITE ou une FAVEUR emprunté provoque sa Souillure.","texte_reference":"Messe de l’IndivisibleProfil: 3 PTV • RITE • R • Rituel prolongé • 1/Scénario • Souillure 21Jusqu’à 7 Communiants offrent chacun une capacité Longinus ou Sombre-Vérité possédée. Pour la scène préparée, chaque capacité offerte peut être utilisée une fois par un autre Communiant à son coût normal. Tous les prérequis de Nature, Source, profondeur et lien restent obligatoires ; RITE/FAVEUR emprunté provoque aussi sa Souillure.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_l_ordre_de_longinus_les_templiers', 'Les Templiers', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_heresie-designee', 'Hérésie désignée', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, V/SR/R, 1 PA, Souillure 15","activation":null,"texte_court":"après avoir vu une créature employer un pouvoir divin, angélique, infernal lié à une autorité religieuse ou une vraie consécration, tu la désignes comme Hérésie pour la scène. Une seule ; pas d''identification complète.","texte_reference":"Hérésie désignéeProfil: 1 PTV • RITE • V/SR/R • 1 PA • Souillure 15Après avoir vu une créature employer pouvoir divin, angélique, infernal lié à une autorité religieuse ou vraie consécration surnaturelle, la désigner comme Hérésie pour la scène. Une seule active ; aucune identification complète.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_traverser-le-sanctuaire', 'Traverser le sanctuaire', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, passif, Souillure 18 ; requiert Hérésie désignée","activation":null,"texte_court":"quand une barrière sacrée ou divine t''empêche de passer, Volonté + Maîtrise spirituelle contre sa Puissance. En réussite, toi seul passes, cette fois ; elle n''est pas détruite.","texte_reference":"Traverser le sanctuaireProfil: 2 PTV • RITE • SR/R • Passif • Prérequis : Hérésie désignée • Souillure 18Lorsqu’une barrière ou interdiction surnaturelle sacrée/divine/religieuse empêche physiquement le Templier de passer : Volonté + Maîtrise spirituelle contre Puissance. En réussite, lui seul franchit cette fois ; la protection n’est pas détruite.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":"Hérésie désignée","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_fer-noir-contre-la-lumiere', 'Fer noir contre la lumière', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 1/scène, Souillure 18","activation":null,"texte_court":"ton arme touchée à un support Profané, ton prochain coup réussi contre l''Hérésie peut affecter une manifestation spirituelle ou divine assez présente pour être combattue. Ni bonus de DGT ni Perforant.","texte_reference":"Fer noir contre la lumièreProfil: 2 PTV • RITE • R • 1/Scène • Souillure 18Après avoir touché son arme à un support Profané Longinus, son prochain coup réussi contre l’Hérésie peut affecter normalement une manifestation spirituelle/divine suffisamment présente pour être combattue. Aucun bonus de DGT ou Perforant.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_martyr-qui-refuse', 'Martyr qui refuse', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, Réaction, 1/scénario, Souillure 18","activation":null,"texte_court":"quand une attaque de l''Hérésie devrait te faire franchir le seuil de Mort, tu restes à 1 PV au-dessus jusqu''à la fin de ta prochaine activation. Sans soins suffisants, tu meurs. Aucun cumul avec une autre survie.","texte_reference":"Martyr qui refuseProfil: 2 PTV • RITE • SR/R • Réaction • 1/Scénario • Souillure 18Lorsqu’une attaque de l’Hérésie devrait faire franchir le seuil de Mort, rester à 1 PV au-dessus du seuil jusqu’à la fin de la prochaine activation. Si le personnage n’est pas suffisamment soigné ensuite, il meurt. Pas de cumul avec une autre survie.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_lance-du-faux-martyr', 'Lance du faux martyr', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, Réaction 1 PA, 1/scène, Souillure 21","activation":null,"texte_court":"quand l''Hérésie fuit par Transcendance, projection, envol surnaturel, abandon du corps ou changement d''état, tu l''attaques aussitôt avec une arme prête. Si tu infliges 1 PV réel, tu connais sa direction et elle reste Hérésie jusqu''à la fin de sa prochaine activation.","texte_reference":"Lance du faux martyrProfil: 3 PTV • RITE • R • Réaction 1 PA • 1/Scène • Souillure 21Quand l’Hérésie active Transcendance, projection, envol surnaturel, abandon du corps ou autre fuite de changement d’état, effectuer une attaque immédiate avec une arme prête. Si elle inflige 1 PV réel, le Templier connaît sa direction générale et la garde comme Hérésie jusqu’à la fin de sa prochaine activation.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_ordre-de-longinus_le-corps-juge', 'Le Corps juge', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA, 1/scène, Souillure 21","activation":null,"texte_court":"jusqu''à la fin du round, la première ouverture surnaturelle qu''un Communiant crée contre l''Hérésie (brèche, perte de Protection, matérialisation, interruption) reste exploitable par les autres. Ni DGT ni succès gratuits.","texte_reference":"Le Corps jugeProfil: 3 PTV • RITE • R • 2 PA • 1/Scène • Souillure 21Jusqu’à la fin du round, la première ouverture surnaturelle réelle créée par un Communiant contre l’Hérésie — brèche, perte de Protection, matérialisation, interruption — reste exploitable par les autres Communiants. Aucun bonus de DGT ni succès gratuit.","lore":null,"groupe_actuel":"V’Aagor — Ordre de Longinus","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Ordre de Longinus","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'corruption', 'corruption_culte_la_confrerie_de_la_faux', 'Culte — la Confrérie de la Faux', NULL, '{"nature":"corruption","chemin":["V''Aagor — la Sombre-Vérité","Culte — la Confrérie de la Faux"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_la_confrerie_de_la_faux_la_proie', 'La Proie', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_confrerie-de-la-faux_ombre-de-la-proie', 'Ombre de la proie', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1 PA, Souillure 15","activation":null,"texte_court":"après avoir touché une cible ou lui avoir infligé 1 PV réel, tu attaches ton ombre à la sienne jusqu''à la fin de la scène : direction générale, présence dans la zone. Son ombre sert de support à la suite.","texte_reference":"Ombre de la proieProfil: 1 PTV • RITE • SR/R • 1 PA • Souillure 15Après avoir touché volontairement une cible ou lui avoir infligé 1 PV réel, rattacher sa propre ombre à la sienne jusqu’à la fin de la scène. Direction générale et présence dans la zone ; son ombre devient support des techniques suivantes.","lore":null,"groupe_actuel":"V’Aagor — Confrérie de la Faux","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Confrérie de la Faux","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_confrerie-de-la-faux_coup-d-angle-mort', 'Coup d''angle mort', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, attaque normale, Souillure 18 ; requiert Ombre de la proie","activation":null,"texte_court":"si une portion de l''ombre de ta Proie est visible à courte portée, ton attaque de Mêlée peut en sortir. Elle se défend normalement ; couvert partiel et angles sont contournés, jamais un mur fermé sans ombre.","texte_reference":"Coup d’angle mortProfil: 2 PTV • RITE • R • Attaque normale • Prérequis : Ombre de la proie • Souillure 18Si une portion de l’ombre de la Proie est visible à courte portée, une attaque de Mêlée peut émerger depuis cette ombre. La cible se défend normalement ; couvert partiel et angles physiques peuvent être contournés, pas un mur fermé sans ombre accessible.","lore":null,"groupe_actuel":"V’Aagor — Confrérie de la Faux","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Confrérie de la Faux","prerequis_texte":"Ombre de la proie","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_la_confrerie_de_la_faux_le_pere_dans_la_chair_faveurs', 'Le Père dans la chair — Faveurs', NULL, '{"nature":"corruption","forme":null,"forme_lot":null,"verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Réflexes prêtés est un bonus défensif fort, mais il est payé par une Souillure 18 à chaque usage. Il est gardé tel quel : ne pas affaiblir préventivement."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_confrerie-de-la-faux_reflexes-pretes', 'Réflexes prêtés', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, V/SR/R, Réaction 1 PA, 1/round, Souillure 18","activation":null,"texte_court":"Surpris, ou empêché de te défendre au premier instant, tu as droit à une Défense active en dépensant un PA déjà déterminé. Aucun PA en plus.","texte_reference":"Réflexes prêtésProfil: 2 PTV • FAVEUR • V/SR/R • Réaction 1 PA • 1/round • Souillure 18Quand le membre est Surpris ou ne pourrait normalement pas défendre activement à cause du moment initial, le Père reprend brièvement ses muscles : Défense active possible en dépensant un PA déjà déterminé. Aucun PA supplémentaire.","lore":null,"groupe_actuel":"V’Aagor — Confrérie de la Faux","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Confrérie de la Faux","prerequis_texte":null,"statut_regle":"correction","changements":"aucun. Réflexes prêtés est un bonus défensif fort, mais il est payé par une Souillure 18 à chaque usage. Il est gardé tel quel : ne pas affaiblir préventivement."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_confrerie-de-la-faux_corps-prete', 'Corps prêté', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, Réaction 1 PA, 1/scène, Souillure 18","activation":null,"texte_court":"quand une mutilation, une paralysie, un membre cassé ou la douleur empêche une action physique simple, le Père commande la chair : Défense active, manipulation ou mouvement concevable. La blessure reste.","texte_reference":"Corps prêtéProfil: 2 PTV • FAVEUR • R • Réaction 1 PA • 1/Scène • Souillure 18Une mutilation locale, paralysie, membre cassé ou douleur empêcherait une action physique simple : le Père commande directement la chair et permet une Défense active, manipulation ou mouvement physiquement concevable. La blessure n’est pas soignée.","lore":null,"groupe_actuel":"V’Aagor — Confrérie de la Faux","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Confrérie de la Faux","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_confrerie-de-la-faux_deux-volontes-dans-la-chair', 'Deux volontés dans la chair', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, SR/R, Réaction 1 PA, 1/scène, Souillure 18","activation":null,"texte_court":"après un échec contre une possession, une domination directe ou une prise de contrôle du corps, Volonté + Maîtrise spirituelle contre sa Puissance. En réussite, l''effet échoue : la place était prise.","texte_reference":"Deux volontés dans la chairProfil: 2 PTV • FAVEUR • SR/R • Réaction 1 PA • 1/Scène • Souillure 18Après échec contre possession, domination directe ou prise de contrôle du corps, Volonté + Maîtrise spirituelle contre Puissance de l’effet. En réussite, l’effet échoue : le siège était déjà occupé.","lore":null,"groupe_actuel":"V’Aagor — Confrérie de la Faux","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Confrérie de la Faux","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_confrerie-de-la-faux_main-du-pere', 'Main du Père', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, R, 2 PA, 1/scène, Souillure 21","activation":null,"texte_court":"tu cèdes le contrôle de ton corps jusqu''à la fin de l''activation. Les limites purement corporelles des blessures et de la douleur n''empêchent plus d''agir ; PV, Agonisant, obstacles et PA restent normaux.","texte_reference":"Main du PèreProfil: 3 PTV • FAVEUR • R • 2 PA • 1/Scène • Souillure 21Céder volontairement le contrôle du corps jusqu’à la fin de l’activation. Les limitations purement corporelles de blessures/douleur n’empêchent pas les actions ; PV, Agonisant, obstacles et PA restent normaux.","lore":null,"groupe_actuel":"V’Aagor — Confrérie de la Faux","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Confrérie de la Faux","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_confrerie-de-la-faux_mort-differee', 'Mort différée', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, R, Réaction, 1/scénario, Souillure 21","activation":null,"texte_court":"au seuil de Mort, le Père refuse de rendre le corps : tu restes à 1 PV au-dessus jusqu''à la fin de ta prochaine activation, puis tu meurs sans soins suffisants. +1 Corruption V''Aagor automatique.","texte_reference":"Mort différéeProfil: 3 PTV • FAVEUR • R • Réaction • 1/Scénario • Souillure 21Au seuil de Mort, le Père refuse de rendre le corps : rester à 1 PV au-dessus du seuil jusqu’à la fin de la prochaine activation. Sans soins suffisants, mort ensuite. En plus de Souillure 21 : +1 Corruption V’Aagor automatique.","lore":null,"groupe_actuel":"V’Aagor — Confrérie de la Faux","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Confrérie de la Faux","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_confrerie-de-la-faux_incarnation-de-la-faux', 'Incarnation de la Faux', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, R, 2 PA, 1/scénario, Souillure 21","activation":null,"texte_court":"jusqu''à la fin de ta prochaine activation, toute ombre visible à courte portée prolonge ta portée physique pour saisir, manipuler ou attaquer au contact, avec tes PA normaux. +1 Corruption V''Aagor automatique.","texte_reference":"Incarnation de la FauxProfil: 3 PTV • FAVEUR • R • 2 PA • 1/Scénario • Souillure 21Jusqu’à la fin de la prochaine activation, toute ombre visible à courte portée compte comme extension de portée physique pour saisir, manipuler ou attaquer au contact avec les PA normaux. En plus de Souillure 21 : +1 Corruption V’Aagor automatique.","lore":null,"groupe_actuel":"V’Aagor — Confrérie de la Faux","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Confrérie de la Faux","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
