INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_fontaine-des-tenebres_entendre-osh-bawa', 'Entendre Osh''Bawa', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, passif, Souillure 15","activation":null,"texte_court":"près d''une forte concentration de Sombre-Vérité, d''essence de la Fontaine, de sang oshirique ou de fragment aagorien, tu sens qu''une Source existe et sa direction générale.","texte_reference":"Entendre Osh’BawaProfil: 1 PTV • RITE • SR/R • Passif • Souillure 15À proximité d’une concentration significative de Sombre-Vérité, essence de la Fontaine, sang Oshirique ou fragment aagorien, sentir qu’une Source existe et sa direction générale. Pas d’identification automatique.","lore":null,"groupe_actuel":"V’Aagor — Fontaine des Ténèbres","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Fontaine des Ténèbres","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_fontaine-des-tenebres_bassin-de-nuit', 'Bassin de nuit', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, préparation, Souillure 18","activation":null,"texte_court":"avec une vraie dose de Fontaine, d''oshirique ou de fragment, tu prépares un petit bassin qui sert de support de Fontaine pour la scène. Le composant est consommé.","texte_reference":"Bassin de nuitProfil: 2 PTV • RITE • SR/R • Préparation • Souillure 18Avec une vraie dose de Fontaine, d’Oshirique ou de fragment approprié, préparer un petit bassin secondaire servant de support de Fontaine pour la scène. Le composant original est consommé.","lore":null,"groupe_actuel":"V’Aagor — Fontaine des Ténèbres","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Fontaine des Ténèbres","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_fontaine-des-tenebres_bapteme-d-osh-bawa', 'Baptême d''Osh''Bawa', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 18","activation":null,"texte_court":"tu immerges une cible consentante, immobilisée ou impuissante dans un support valide : exposition réelle à V''Aagor selon le vecteur. Une cible qui résiste n''est pas forcément corrompue.","texte_reference":"Baptême d’Osh’BawaProfil: 2 PTV • RITE • SR/R • Rituel • Souillure 18Immerger une cible consentante, immobilisée ou impuissante dans un support valide et provoquer une exposition réelle à V’Aagor selon le vecteur approprié. Le rite ne garantit pas la corruption d’une cible résistante.","lore":null,"groupe_actuel":"V’Aagor — Fontaine des Ténèbres","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Fontaine des Ténèbres","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_fontaine-des-tenebres_boire-ce-qui-est-noir', 'Boire ce qui est noir', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, Vampire, SR/R, passif, Souillure 18","activation":null,"texte_court":"quand tu te nourris sur une créature qui porte au moins 1 Corruption V''Aagor, ton sang soutient les rites de Fontaine pendant la scène. Ni soin ni vol de pouvoir.","texte_reference":"Boire ce qui est noirProfil: 2 PTV • RITE • Vampire uniquement • SR/R • Passif • Souillure 18Lorsqu’un Vampire du culte se nourrit sur une créature portant au moins 1 Corruption V’Aagor, son sang compte comme suffisamment chargé de Sombre-Vérité pour soutenir les rites de Fontaine pendant la scène. Pas de soin bonus ni vol de pouvoir.","lore":null,"groupe_actuel":"V’Aagor — Fontaine des Ténèbres","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Fontaine des Ténèbres","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_fontaine-des-tenebres_noircir-la-coupe', 'Noircir la coupe', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, Vampire, R, 1/scène, Souillure 18","activation":null,"texte_court":"après une vraie Prédation sur un vivant, tu laisses de la Sombre-Vérité dans la plaie : Vigueur + Constitution contre 15, une exposition par cible et par scène.","texte_reference":"Noircir la coupeProfil: 2 PTV • RITE • Vampire • R • 1/Scène • Souillure 18Après une vraie Prédation sur une cible vivante, laisser une trace de Sombre-Vérité dans la plaie : Vigueur + Constitution difficulté 15, une exposition par cible et par scène.","lore":null,"groupe_actuel":"V’Aagor — Fontaine des Ténèbres","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Fontaine des Ténèbres","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_fontaine-des-tenebres_rien-ne-quitte-la-fontaine', 'Rien ne quitte la Fontaine', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, SR/R, Réaction 1 PA, 1/scène, Souillure 21","activation":null,"texte_court":"quand une purification retire 1 Corruption V''Aagor à une personne perçue, elle marche, mais tu peux récupérer ce point : +1 Corruption V''Aagor pour toi.","texte_reference":"Rien ne quitte la FontaineProfil: 3 PTV • RITE • SR/R • Réaction 1 PA • 1/Scène • Souillure 21Lorsqu’une purification retire 1 Corruption V’Aagor à une personne perçue, la purification fonctionne mais le prêtre peut récupérer ce point : il gagne +1 Corruption V’Aagor. Souillure 21 s’applique en plus.","lore":null,"groupe_actuel":"V’Aagor — Fontaine des Ténèbres","kind":"RITE","profondeur":null,"source":"vaagor","famille":"Fontaine des Ténèbres","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
