INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_les_messagers_de_l_oeil_blanc_la_couture_et_la_masse', 'La couture et la masse', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_messagers-de-l-il-blanc_voir-la-couture', 'Voir la couture', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"FAVEUR, SR/R, passif, Souillure 15","activation":null,"texte_court":"quand un phénomène perçu implique une frontière dimensionnelle, un passage vers l''Ombre-Monde ou une extraction de plan, tu sais que la couture est là. Ni méthode d''ouverture ni responsable.","texte_reference":"Voir la coutureProfil: 1 PTV • FAVEUR • SR/R • Passif • Souillure 15Lorsqu’un phénomène surnaturel perçu implique réellement frontière dimensionnelle, passage vers l’Ombre-Monde ou extraction de plan, le Messager sait que cette couture est présente. Pas de méthode d’ouverture ni identification du responsable.","lore":null,"groupe_actuel":"V’Aagor — Messagers de l’Œil Blanc","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Messagers de l’Œil Blanc","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_messagers-de-l-il-blanc_masse-empruntee', 'Masse empruntée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1 PA, Souillure 18","activation":null,"texte_court":"jusqu''au début de ta prochaine activation, tu t''allèges fortement ou t''alourdis au point qu''une force humaine ordinaire ne te déplace pas. Ni bonus de DGT ; le support peut céder.","texte_reference":"Masse empruntéeProfil: 2 PTV • FAVEUR • R • 1 PA • Souillure 18Jusqu’au début de la prochaine activation, alléger fortement sa masse ou l’alourdir au point qu’une force humaine ordinaire ne puisse le déplacer. Aucun bonus de DGT ; le support peut céder.","lore":null,"groupe_actuel":"V’Aagor — Messagers de l’Œil Blanc","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Messagers de l’Œil Blanc","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_messagers-de-l-il-blanc_pression-invisible', 'Pression invisible', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1 PA, Souillure 18","activation":null,"texte_court":"tu attires ou repousses brutalement une cible à courte portée ; si elle résiste, Volonté + Maîtrise spirituelle contre Vigueur + Athlétisme. En réussite, quelques mètres de déplacement, ou une chute si la situation s''y prête. Aucun DGT automatique.","texte_reference":"Pression invisibleProfil: 2 PTV • FAVEUR • R • 1 PA • Souillure 18Attirer ou repousser brutalement une cible à courte portée. Créature réticente : Volonté + Maîtrise spirituelle contre Vigueur + Athlétisme. En réussite, déplacement de quelques mètres ou chute si la situation s’y prête. Pas de DGT automatique.","lore":null,"groupe_actuel":"V’Aagor — Messagers de l’Œil Blanc","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Messagers de l’Œil Blanc","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_messagers-de-l-il-blanc_ancre-gravitationnelle', 'Ancre gravitationnelle', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1 PA, Souillure 18","activation":null,"texte_court":"contre la Défense occulte d''une cible vivante. En réussite, jusqu''à la fin de sa prochaine activation, elle reste fixée à son support : mouvement normal, mais aucune capacité de départ instantané, d''absence de masse ou de bascule dimensionnelle.","texte_reference":"Ancre gravitationnelleProfil: 2 PTV • FAVEUR • R • 1 PA • Souillure 18Sur cible vivante : Défense occulte. En réussite jusqu’à la fin de sa prochaine activation, elle reste fixée à son référentiel matériel : mouvement normal sur le support, mais pas de capacité surnaturelle exigeant départ instantané, absence de masse ou bascule dimensionnelle.","lore":null,"groupe_actuel":"V’Aagor — Messagers de l’Œil Blanc","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Messagers de l’Œil Blanc","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_messagers-de-l-il-blanc_etouffement-du-mageius', 'Étouffement du Mageius', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, R, Réaction 1 PA, 1/scène, Souillure 21","activation":null,"texte_court":"quand un Mage perçu à courte portée lance une Magie, Volonté + Maîtrise spirituelle contre le résultat du sort. En réussite, le sort échoue ; ses PA et son usage limité sont consommés. Magie seulement.","texte_reference":"Étouffement du MageiusProfil: 3 PTV • FAVEUR • R • Réaction 1 PA • 1/Scène • Souillure 21Lorsqu’un Mage perçu à courte portée active une Magie : Volonté + Maîtrise spirituelle contre le résultat du sort. En réussite, la manifestation échoue avant de se stabiliser ; PA et usage limité éventuel sont consommés. Magie uniquement.","lore":null,"groupe_actuel":"V’Aagor — Messagers de l’Œil Blanc","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Messagers de l’Œil Blanc","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vaagor_messagers-de-l-il-blanc_ecarter-la-couture', 'Écarter la couture', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, R, 2 PA, 1/scène, Souillure 21 ; requiert Voir la couture","activation":null,"texte_court":"sur une faiblesse dimensionnelle identifiée, tu ouvres une fenêtre pendant un round : vue, son, petit objet ou effet capable de passer, jamais une personne entière.","texte_reference":"Écarter la coutureProfil: 3 PTV • FAVEUR • R • 2 PA • 1/Scène • Prérequis : Voir la couture • Souillure 21Sur une faiblesse dimensionnelle identifiée, forcer une ouverture de taille fenêtre pendant un round. Elle laisse passer vue, son, petit objet ou effet pouvant réellement franchir l’ouverture, mais pas une personne entière.","lore":null,"groupe_actuel":"V’Aagor — Messagers de l’Œil Blanc","kind":"FAVEUR","profondeur":null,"source":"vaagor","famille":"Messagers de l’Œil Blanc","prerequis_texte":"Voir la couture","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
