INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_division_les_lignes_de_coupe', 'Les lignes de coupe', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_voir-les-jointures', 'Voir les jointures', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"tu perçois dans un objet, un organisme, un phénomène ou une structure une vraie frontière ou dépendance (joint, organe qui alimente une fonction, source extérieure, deux essences distinctes). Ni faiblesse ni fonctionnement complet.","texte_reference":"Voir les jointuresProfil: 1 PTV • DON • Marqué • SR/R • 1 PAPercevoir dans un objet, organisme, phénomène ou structure une véritable frontière, interface ou dépendance : joint, organe alimentant une fonction, source extérieure, deux essences distinctes. Pas de faiblesse ni fonctionnement complet automatique.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Marqué","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_detacher-sans-briser', 'Détacher sans briser', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"au contact d''un objet non vivant, tu sépares proprement deux éléments déjà assemblés (collage, soudure, sertissage, emboîtement). Un assemblage surnaturel oppose sa Puissance.","texte_reference":"Détacher sans briserProfil: 1 PTV • DON • Marqué • SR/R • 1 PAAu contact d’un objet non vivant, séparer proprement deux éléments possédant déjà une interface réelle : collage, soudure, sertissage, emboîtement. Un assemblage surnaturel oppose sa Puissance.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Marqué","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_couper-le-lien', 'Couper le lien', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, SR/R, 1 PA, 1/scène","activation":null,"texte_court":"sur un lien surnaturel perçu ou identifié, Volonté + Maîtrise spirituelle contre sa Puissance. En réussite, il est interrompu jusqu''à la fin de la prochaine activation de sa source. Ni lien de Nature, ni lien naturel âme-corps.","texte_reference":"Couper le lienProfil: 2 PTV • DON • Envahi • SR/R • 1 PA • 1/ScèneSur un lien surnaturel perçu ou identifié : Volonté + Maîtrise spirituelle contre Puissance. En réussite, le lien est interrompu jusqu’à la fin de la prochaine activation de sa Source. Pas de coupure de Nature intrinsèque ni de lien âme-corps naturel.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Envahi","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_separer-la-fonction', 'Séparer la fonction', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA, 1/scène","activation":null,"texte_court":"tu choisis une fonction observée (régénération, vision surnaturelle, organe, brouilleur, venin, module). Contre une créature, Volonté + Maîtrise spirituelle contre Défense occulte ; en réussite, la fonction cesse jusqu''à la fin de sa prochaine activation.","texte_reference":"Séparer la fonctionProfil: 3 PTV • DON • Envahi • R • 1 PA • 1/ScèneChoisir une fonction précise réellement observée : régénération, vision surnaturelle, organe, brouilleur, venin, module. Contre créature : Volonté + Maîtrise spirituelle contre Défense occulte ; en réussite la fonction cesse jusqu’à la fin de la prochaine activation.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Envahi","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_fracturer-la-protection', 'Fracturer la protection', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA, 1/scène","activation":null,"texte_court":"après avoir vu une Protection surnaturelle fonctionner, Volonté + Maîtrise spirituelle contre sa Puissance. En réussite, elle cesse de protéger jusqu''à la fin de la prochaine activation de la cible.","texte_reference":"Fracturer la protectionProfil: 3 PTV • DON • Envahi • R • 1 PA • 1/ScèneAprès avoir vu une Protection surnaturelle fonctionner, tenter de la séparer de ce qu’elle protège : Volonté + Maîtrise spirituelle contre Puissance. En réussite elle cesse de protéger jusqu’à la fin de la prochaine activation de la cible.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Envahi","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_scinder-le-pouvoir', 'Scinder le pouvoir', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"contre un pouvoir que cette source a déjà utilisé dans la scène, Volonté + Maîtrise spirituelle contre son résultat ou sa Puissance lors d''une activation suivante. En réussite, il est séparé de sa source avant de se stabiliser ; PA et usage sont consommés.","texte_reference":"Scinder le pouvoirProfil: 3 PTV • DON • Au bord • R • Réaction 1 PA • 1/ScèneAprès avoir déjà observé ce pouvoir précis utilisé par cette Source dans la scène, Volonté + Maîtrise spirituelle contre résultat/Puissance lors d’une activation suivante. En réussite la manifestation est séparée de sa Source avant stabilisation ; PA/usage sont consommés.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Au bord de la Rupture","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_division_se_scinder', 'Se scinder', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Séparer la douleur ressemble à Dévorer la douleur (Vhodhal) : on garde les deux (A4). Ici la douleur est mise à part, en Réaction ; là elle est consommée, pour 1 PA."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_memoire-en-eclat', 'Mémoire en éclat', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"tu isoles un souvenir précis jusqu''à la fin de la scène. Toi-même ne t''en souviens plus ; une altération surnaturelle doit vaincre ta Volonté + Maîtrise spirituelle pour modifier ce fragment. Il revient ensuite.","texte_reference":"Mémoire en éclatProfil: 1 PTV • DON • Marqué • SR/R • 1 PAIsoler un souvenir précis jusqu’à la fin de la scène. Le porteur ne peut lui-même plus s’en souvenir ; une altération surnaturelle générique doit vaincre Volonté + Maîtrise spirituelle spécifiquement pour modifier ce fragment. Il est réintégré ensuite.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Marqué","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_separer-la-douleur', 'Séparer la douleur', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"tu isoles la douleur d''une blessure jusqu''à la fin de la scène. PV, mutilations et fonctions détruites restent ; seules douleur, spasmes et incapacité due à la souffrance cessent.","texte_reference":"Séparer la douleurProfil: 2 PTV • DON • Marqué • SR/R • Réaction 1 PA • 1/ScèneIsoler la douleur d’une blessure jusqu’à la fin de la scène. PV, mutilations et fonctions réellement détruites restent ; seules douleur, spasmes ou incapacité due uniquement à la souffrance cessent de gêner.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Marqué","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"correction","changements":"aucun. Séparer la douleur ressemble à Dévorer la douleur (Vhodhal) : on garde les deux (A4). Ici la douleur est mise à part, en Réaction ; là elle est consommée, pour 1 PA."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_prisme-defensif', 'Prisme défensif', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"contre un effet surnaturel direct à au moins deux conséquences distinctes, Volonté + Maîtrise spirituelle contre sa Puissance. En réussite, une composante ne s''applique pas à toi.","texte_reference":"Prisme défensifProfil: 2 PTV • DON • Marqué • SR/R • Réaction 1 PA • 1/ScèneLorsqu’un effet surnaturel direct possède au moins deux conséquences réellement distinctes, Volonté + Maîtrise spirituelle contre Puissance. En réussite, choisir une composante qui ne s’applique pas au porteur ; l’autre se résout normalement.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Marqué","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_scinder-l-elan', 'Scinder l''élan', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, SR/R, Réaction 1 PA, 1/round","activation":null,"texte_court":"quand un choc matériel te touche, les dégâts restent, mais une conséquence d''élan (projection, renversement, entraînement, recul forcé) est annulée.","texte_reference":"Scinder l’élanProfil: 2 PTV • DON • Envahi • SR/R • Réaction 1 PA • 1/roundQuand un choc matériel touche le porteur, les dégâts restent mais une conséquence reposant explicitement sur l’élan — projection, renversement, entraînement, recul forcé — peut être annulée.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Envahi","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_compartimenter-l-esprit', 'Compartimenter l''esprit', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, SR/R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"une influence mentale surnaturelle qui vient de prendre effet est isolée jusqu''à la fin de ta prochaine activation. Elle ne dicte rien pendant ce temps, puis revient si elle n''a pas été brisée.","texte_reference":"Compartimenter l’espritProfil: 2 PTV • DON • Envahi • SR/R • Réaction 1 PA • 1/ScèneLorsqu’une influence mentale surnaturelle vient de prendre effet, l’isoler jusqu’à la fin de la prochaine activation. Elle ne peut dicter les actions pendant cet intervalle mais revient ensuite si elle n’a pas été réellement brisée.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Envahi","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_diviser-l-effet', 'Diviser l''effet', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"quand un phénomène surnaturel de zone devrait t''affecter, Volonté + Maîtrise spirituelle contre sa Puissance. En réussite, ta portion est séparée : tu n''es pas affecté, le reste continue.","texte_reference":"Diviser l’effetProfil: 3 PTV • DON • Envahi • R • Réaction 1 PA • 1/ScèneLorsqu’un phénomène surnaturel de zone devrait affecter le porteur, Volonté + Maîtrise spirituelle contre Puissance. En réussite, la portion correspondant à sa position est séparée : il n’est pas affecté, le phénomène continue normalement ailleurs.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Envahi","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_scission-de-survie', 'Scission de survie', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction, 1/scénario","activation":null,"texte_court":"quand une blessure physique localisable devrait te faire franchir le seuil de Mort, tu sépares la partie condamnée : 0 PV, Stabilisé, avec une mutilation majeure permanente. +1 Corruption Sharith automatique.","texte_reference":"Scission de survieProfil: 3 PTV • DON • Au bord • R • Réaction • 1/ScénarioUne blessure physique localisable devrait faire franchir le seuil de Mort : le porteur sépare immédiatement la partie condamnée, survit à 0 PV Stabilisé mais subit une mutilation majeure permanente appropriée. +1 Corruption Sharith automatique.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Au bord de la Rupture","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_division_scinder-le-moi', 'Scinder le Moi', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 1 PA, 1/scène","activation":null,"texte_court":"tu isoles une émotion, une compulsion, des souvenirs, un attachement ou une influence psychique jusqu''à la fin de la scène. Si tu isoles une part fondamentale pour faire ce que tu aurais refusé : +1 Corruption Sharith automatique.","texte_reference":"Scinder le MoiProfil: 3 PTV • DON • Au bord • R • 1 PA • 1/ScèneIsoler émotion, compulsion, ensemble de souvenirs, attachement ou influence psychique identifiée jusqu’à la fin de la scène. La partie revient ensuite. Si une composante fondamentale est isolée pour accomplir volontairement un acte que le personnage aurait refusé : +1 Corruption Sharith automatique.","lore":null,"groupe_actuel":"Ux’Sharith — Division","kind":"DON","profondeur":"Au bord de la Rupture","source":"sharith","famille":"Division","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
