INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_le_grand_savoir_archilogomancie_l_oeil_d_or', 'L''Œil d''Or', NULL, '{"nature":"corruption","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"**référence cassée réparée**. Illumination et Erreur forcée demandaient Analyse 4, qu''aucun Rite ne donnait. Révélation, qui suit Compréhension, donne désormais **Analyse 4**. Aucun coût ni effet ne change. Le rapport 09 proposait plutôt un rang 4 nouveau : refusé, il ajoutait un pouvoir."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_grand-savoir_observation', 'Observation', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1 PA, Souillure 15","activation":null,"texte_court":"**Analyse 1** d''une cible visible. Tu distingues ses grandes couches fonctionnelles sans leurs mécanismes.","texte_reference":"ObservationProfil: 1 PTV • RITE • SR/R • 1 PA • Souillure 15Poser l’Œil d’Or sur une cible visible : Analyse 1. Distinguer les grandes couches fonctionnelles réelles sans comprendre encore leurs mécanismes.","lore":null,"groupe_actuel":"Ux’Sharith — Grand Savoir","kind":"RITE","profondeur":null,"source":"sharith","famille":"Grand Savoir","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
