INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_grand-savoir_comprehension', 'Compréhension', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1 PA, Souillure 18 ; Analyse 2","activation":null,"texte_court":"**Analyse 3**. Tu proposes une modification précise ; le MJ dit sa conséquence principale. Rien n''est réalisé.","texte_reference":"CompréhensionProfil: 2 PTV • RITE • SR/R • 1 PA • Analyse 2 • Souillure 18Analyse 3 : choisir une modification hypothétique précise ; le MJ indique la conséquence réelle principale qu’aurait cette modification. Le Rite ne réalise rien.","lore":null,"groupe_actuel":"Ux’Sharith — Grand Savoir","kind":"RITE","profondeur":null,"source":"sharith","famille":"Grand Savoir","prerequis_texte":null,"statut_regle":"correction","changements":"**référence cassée réparée**. Illumination et Erreur forcée demandaient Analyse 4, qu''aucun Rite ne donnait. Révélation, qui suit Compréhension, donne désormais **Analyse 4**. Aucun coût ni effet ne change. Le rapport 09 proposait plutôt un rang 4 nouveau : refusé, il ajoutait un pouvoir."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
