INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_grand-savoir_illumination', 'Illumination', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA ou étude prolongée, Souillure 21 ; Analyse 4","activation":null,"texte_court":"**Analyse 5**. Le MJ révèle une modification réellement possible pour améliorer, détourner, adapter ou reconfigurer une fonction. Matériaux, outils, Compétences et temps restent nécessaires.","texte_reference":"IlluminationProfil: 3 PTV • RITE • R • 2 PA ou étude prolongée • Analyse 4 • Souillure 21Analyse 5 : demander comment la cible pourrait fonctionner autrement. Le MJ révèle une modification réellement possible permettant d’améliorer, détourner, adapter ou reconfigurer une fonction. Matériaux, outils, Compétences et temps restent nécessaires.","lore":null,"groupe_actuel":"Ux’Sharith — Grand Savoir","kind":"RITE","profondeur":null,"source":"sharith","famille":"Grand Savoir","prerequis_texte":null,"statut_regle":"correction","changements":"**référence cassée réparée**. Illumination et Erreur forcée demandaient Analyse 4, qu''aucun Rite ne donnait. Révélation, qui suit Compréhension, donne désormais **Analyse 4**. Aucun coût ni effet ne change. Le rapport 09 proposait plutôt un rang 4 nouveau : refusé, il ajoutait un pouvoir."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
