INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_grand-savoir_analyse-parallele', 'Analyse parallèle', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, passif, Souillure 18","activation":null,"texte_court":"tu maintiens deux cibles analysées à la fois. Sans ce Rite, commencer une seconde analyse sous pression fait perdre la première.","texte_reference":"Analyse parallèleProfil: 2 PTV • RITE • SR/R • Passif • Souillure 18Maintenir simultanément deux cibles analysées ; sans ce Rite, commencer une seconde analyse détaillée sous pression fait perdre la première.","lore":null,"groupe_actuel":"Ux’Sharith — Grand Savoir","kind":"RITE","profondeur":null,"source":"sharith","famille":"Grand Savoir","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_grand-savoir_iteration-fulgurante', 'Itération fulgurante', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1/scène, Souillure 18","activation":null,"texte_court":"après une étape d''Analyse réussie, tu enchaînes l''étape suivante pour 1 PA de moins (minimum 1). Chaque étape provoque sa propre Souillure.","texte_reference":"Itération fulguranteProfil: 2 PTV • RITE • SR/R • 1/Scène • Souillure 18Après réussite d’une étape d’Analyse, effectuer immédiatement l’étape suivante pour 1 PA de moins, minimum 1 PA. Chaque étape surnaturelle utilisée provoque sa propre Souillure selon son coût.","lore":null,"groupe_actuel":"Ux’Sharith — Grand Savoir","kind":"RITE","profondeur":null,"source":"sharith","famille":"Grand Savoir","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
