INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_grand-savoir_verite-sous-le-masque', 'Vérité sous le masque', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, passif, Souillure 18 ; Analyse 3","activation":null,"texte_court":"sur une cible V, tu sais si l''Hologramme participe à la cohérence de ce que tu observes. Tu peux savoir que le corps humain n''est pas son architecture réelle, sans voir sa forme vraie ni son espèce.","texte_reference":"Vérité sous le masqueProfil: 2 PTV • RITE • SR/R • Passif • Analyse 3 • Souillure 18Sur une cible V, déterminer si l’Hologramme participe activement à la cohérence fonctionnelle observée. Le cultiste peut savoir que le corps humain n’est pas l’architecture fondamentale sans voir la forme vraie ni identifier l’espèce.","lore":null,"groupe_actuel":"Ux’Sharith — Grand Savoir","kind":"RITE","profondeur":null,"source":"sharith","famille":"Grand Savoir","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_grand-savoir_point-de-rupture', 'Point de rupture', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, Souillure 18 ; Analyse 3+","activation":null,"texte_court":"le MJ indique un vrai moyen concret de perturber la fonction choisie. Le Rite ne crée aucune faiblesse ; il faut les Compétences pour l''exploiter.","texte_reference":"Point de ruptureProfil: 2 PTV • RITE • SR/R • Analyse 3+ • Souillure 18Le MJ indique un véritable vecteur concret d’intervention capable de perturber une fonction choisie. Le Rite ne crée pas de faiblesse inexistante et les Compétences ordinaires restent nécessaires pour l’exploiter.","lore":null,"groupe_actuel":"Ux’Sharith — Grand Savoir","kind":"RITE","profondeur":null,"source":"sharith","famille":"Grand Savoir","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
