INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_grand-savoir_conception-impossible', 'Conception impossible', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, étude prolongée, Souillure 21 ; requiert Illumination","activation":null,"texte_court":"tu définis un résultat précis qu''un système ne sait pas produire. S''il est possible sans violer sa Nature, le MJ révèle l''architecture théorique pour y parvenir.","texte_reference":"Conception impossibleProfil: 3 PTV • RITE • R • Étude prolongée • Prérequis : Illumination • Souillure 21Définir un résultat technique ou métaphysique précis qu’un système existant ne sait normalement pas produire. S’il est possible sans violer sa Nature fondamentale, le MJ révèle une architecture/modification théorique pour y parvenir.","lore":null,"groupe_actuel":"Ux’Sharith — Grand Savoir","kind":"RITE","profondeur":null,"source":"sharith","famille":"Grand Savoir","prerequis_texte":"Illumination","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
