INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_bellatheis_mutation', 'Mutation', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA, Souillure 18","activation":null,"texte_court":"tu modifies une structure de ton corps pour une fonction physiquement concevable (griffes, branchies, articulation, mâchoire, membranes, yeux déplacés). Ni PA ni Talent copiés.","texte_reference":"MutationProfil: 2 PTV • RITE • R • 2 PA • Souillure 18Modifier une structure corporelle existante pour une fonction physiquement concevable : griffes, branchies, articulation, mâchoire, membranes, yeux repositionnés. Aucun PA ou Talent surnaturel copié.","lore":null,"groupe_actuel":"Ux’Sharith — Bellatheis","kind":"RITE","profondeur":null,"source":"sharith","famille":"Bellatheis","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_bellatheis_cloisonnement-tissulaire', 'Cloisonnement tissulaire', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, Réaction 1 PA, 1/scène, Souillure 18","activation":null,"texte_court":"quand un poison, un parasite, une infection ou une corruption biologique localisée se répand, tu isoles la zone jusqu''à la fin de la scène. Rien n''est guéri ; la propagation s''arrête.","texte_reference":"Cloisonnement tissulaireProfil: 2 PTV • RITE • SR/R • Réaction 1 PA • 1/Scène • Souillure 18Lorsqu’un poison, parasite, infection ou corruption biologique localisée commence à se répandre, isoler physiquement la zone jusqu’à la fin de la scène. Rien n’est guéri, seule la propagation reposant sur continuité biologique est suspendue.","lore":null,"groupe_actuel":"Ux’Sharith — Bellatheis","kind":"RITE","profondeur":null,"source":"sharith","famille":"Bellatheis","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_bellatheis_putrefaction', 'Putréfaction', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA, Souillure 21","activation":null,"texte_court":"attaque surnaturelle au contact ou à courte portée, Volonté + Maîtrise spirituelle contre Défense occulte. En réussite, nécrose : 3 PV que l''Armure matérielle ne réduit pas, une fois par round et par cible. Sans effet sur une machine ou un cadavre.","texte_reference":"PutréfactionProfil: 3 PTV • RITE • R • 1 PA • Souillure 21Attaque surnaturelle à courte portée/contact : Volonté + Maîtrise spirituelle contre Défense occulte. En réussite, nécrose brutale de tissu vivant : 3 PV irréductibles par Armure matérielle, maximum une fois par round et par cible. Aucun effet sur machines/cadavres sans physiologie active.","lore":null,"groupe_actuel":"Ux’Sharith — Bellatheis","kind":"RITE","profondeur":null,"source":"sharith","famille":"Bellatheis","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
