INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_bellatheis_porte-entrouverte', 'Porte entrouverte', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel intime, 1/scène, Souillure 18","activation":null,"texte_court":"une propriété corporelle intrinsèque simple déjà identifiée est reproduite chez toi jusqu''à la fin de la scène (venin, respiration, vision, griffes, résistance). Jamais une Nature, un Mageius, l''immortalité ni un Talent complet.","texte_reference":"Porte entrouverteProfil: 2 PTV • RITE • R • Rituel intime • 1/Scène • Souillure 18Après identification d’une propriété corporelle intrinsèque simple, la reproduire jusqu’à la fin de la scène : venin, respiration, vision, griffes naturelles, résistance physiologique. Jamais Nature, Mageius, immortalité ou Talent complet.","lore":null,"groupe_actuel":"Ux’Sharith — Bellatheis","kind":"RITE","profondeur":null,"source":"sharith","famille":"Bellatheis","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_bellatheis_porte-des-secrets', 'Porte des Secrets', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel prolongé, 1/scénario, Souillure 21","activation":null,"texte_court":"une propriété corporelle surnaturelle identifiée passe à toi jusqu''à la fin du scénario, et la cible ne peut plus l''utiliser. Sans consentement, Volonté + Maîtrise spirituelle contre Défense occulte. Une seule volée. +1 Corruption Sharith automatique.","texte_reference":"Porte des SecretsProfil: 3 PTV • RITE • R • Rituel prolongé • 1/Scénario • Souillure 21Choisir une propriété corporelle surnaturelle déjà identifiée. Si le partenaire ne consent pas : Volonté + Maîtrise spirituelle contre Défense occulte. Jusqu’à la fin du scénario le cultiste possède la propriété et la cible ne peut plus l’utiliser. Une seule volée ; +1 Corruption Sharith automatique en plus de Souillure 21.","lore":null,"groupe_actuel":"Ux’Sharith — Bellatheis","kind":"RITE","profondeur":null,"source":"sharith","famille":"Bellatheis","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
