INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_nucleomancie_vision-radioscopique', 'Vision radioscopique', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1 PA, Souillure 15","activation":null,"texte_court":"tu lis densités et structures derrière une épaisseur raisonnable de matière. Ni couleur, ni identité, ni détail que le rayonnement ne donnerait pas.","texte_reference":"Vision radioscopiqueProfil: 1 PTV • RITE • SR/R • 1 PA • Souillure 15Lire densités et structures derrière une épaisseur raisonnable de matière par flux radioscopique. Pas de couleur, identité ni détail que le principe ne pourrait produire.","lore":null,"groupe_actuel":"Ux’Sharith — Nucléomancie","kind":"RITE","profondeur":null,"source":"sharith","famille":"Nucléomancie","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_nucleomancie_degagement-de-chaleur', 'Dégagement de chaleur', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA, [Irradiant], Souillure 18","activation":null,"texte_court":"tu chauffes brutalement une cible. Sur une créature, attaque à distance DGT 7 thermique ; sur un objet, combustion, dilatation ou fusion selon le matériau.","texte_reference":"Dégagement de chaleurProfil: 2 PTV • RITE • R • 1 PA • [Irradiant] • Souillure 18Chauffer brutalement une cible matérielle. Sur créature : attaque à distance DGT 7 thermique. Sur objet : combustion, dilatation ou fusion selon le matériau. Souillure physique (Vigueur + Constitution).","lore":null,"groupe_actuel":"Ux’Sharith — Nucléomancie","kind":"RITE","profondeur":null,"source":"sharith","famille":"Nucléomancie","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_nucleomancie_transmutation-descendante', 'Transmutation descendante', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, [Irradiant], Souillure 18","activation":null,"texte_court":"une quantité limitée d''un élément assez pur devient un élément de numéro atomique inférieur. Les molécules ne se réorganisent pas d''elles-mêmes.","texte_reference":"Transmutation descendanteProfil: 2 PTV • RITE • R • Rituel • [Irradiant] • Souillure 18Sur une quantité limitée d’un élément relativement pur, provoquer une transformation vers un élément de numéro atomique inférieur. Ne réorganise pas automatiquement les molécules. Souillure physique.","lore":null,"groupe_actuel":"Ux’Sharith — Nucléomancie","kind":"RITE","profondeur":null,"source":"sharith","famille":"Nucléomancie","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_nucleomancie_erosion-isotopique', 'Érosion isotopique', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA, [Irradiant], Souillure 18","activation":null,"texte_court":"attaque à courte portée, DGT 8. Sur un objet non protégé, une Altération peut devenir une dégradation durable.","texte_reference":"Érosion isotopiqueProfil: 2 PTV • RITE • R • 1 PA • [Irradiant] • Souillure 18Attaque à courte portée DGT 8. Sur objet non protégé, une Altération peut devenir dégradation structurelle durable. Souillure physique.","lore":null,"groupe_actuel":"Ux’Sharith — Nucléomancie","kind":"RITE","profondeur":null,"source":"sharith","famille":"Nucléomancie","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_nucleomancie_fission-locale', 'Fission locale', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA, 1/scène, [Irradiant], Souillure 18","activation":null,"texte_court":"tu désagrèges la surface d''un petit volume de matière (ouvrir un trou, détruire un mécanisme, découper une protection). Jamais une personne d''un coup.","texte_reference":"Fission localeProfil: 2 PTV • RITE • R • 1 PA • 1/Scène • [Irradiant] • Souillure 18Désagréger rapidement la structure atomique superficielle d’un petit volume matériel : ouvrir un trou, détruire un mécanisme, découper une protection. Pas de désintégration instantanée d’une personne. Souillure physique.","lore":null,"groupe_actuel":"Ux’Sharith — Nucléomancie","kind":"RITE","profondeur":null,"source":"sharith","famille":"Nucléomancie","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_nucleomancie_irradiation-chaotique', 'Irradiation chaotique', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA, 1/scène, [Irradiant], Souillure 21","activation":null,"texte_court":"zone de quelques mètres. Chaque créature biologique fait Vigueur + Constitution contre ta Volonté + Maîtrise spirituelle ; en échec, 4 PV radiologiques surnaturels. Seule une Armure adaptée aux radiations protège.","texte_reference":"Irradiation chaotiqueProfil: 3 PTV • RITE • R • 2 PA • 1/Scène • [Irradiant] • Souillure 21Zone de quelques mètres. Chaque créature biologique : Vigueur + Constitution contre Volonté + Maîtrise spirituelle du Nucléomancien ; en échec 4 PV radiologiques surnaturels, Armure matérielle seulement si adaptée aux radiations. Souillure physique.","lore":null,"groupe_actuel":"Ux’Sharith — Nucléomancie","kind":"RITE","profondeur":null,"source":"sharith","famille":"Nucléomancie","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_sharith_nucleomancie_faisceau-de-fracture', 'Faisceau de fracture', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA, 1/scène, [Irradiant], Souillure 21","activation":null,"texte_court":"attaque de Tir surnaturelle, DGT 12, portée 80 m. Sur une marge d''Altération, une destruction matérielle ou une irradiation cohérente.","texte_reference":"Faisceau de fractureProfil: 3 PTV • RITE • R • 2 PA • 1/Scène • [Irradiant] • Souillure 21Attaque de Tir surnaturelle, DGT 12, portée 80 m. Sur une marge permettant Altération, choisir une conséquence cohérente de destruction matérielle ou irradiation. Souillure physique.","lore":null,"groupe_actuel":"Ux’Sharith — Nucléomancie","kind":"RITE","profondeur":null,"source":"sharith","famille":"Nucléomancie","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
