INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_metastase_la_fonction_reaffectee', 'La fonction réaffectée', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_sens-de-la-fonction', 'Sens de la fonction', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"devant un organe surnaturel, une capacité biologique, une technologie alien, un composant technomagique ou un phénomène de Vérité, tu perçois la fonction concrète d''un élément. Ni fonctionnement complet, ni faiblesse, ni compétence de réparation.","texte_reference":"Sens de la fonctionProfil: 1 PTV • DON • Marqué • SR/R • 1 PAObserver organe surnaturel, capacité biologique, technologie alien, composant technomagique ou phénomène de Vérité et percevoir la fonction concrète remplie par un élément. Pas de fonctionnement complet, faiblesse ni compétence de réparation.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Marqué","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_reaffecter-l-outil', 'Réaffecter l''outil', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, R, 1 PA","activation":null,"texte_court":"au contact, un objet simple remplit pour la scène une fonction physique voisine de ce que sa matière permet (corde rigide, plaque ressort, tissu étanche, barre articulée). Jamais une pierre en ordinateur.","texte_reference":"Réaffecter l’outilProfil: 2 PTV • DON • Marqué • R • 1 PAAu contact d’un objet non vivant simple, lui faire remplir pour la scène une fonction physique voisine de ce que sa matière permet : corde rigide, plaque ressort, tissu étanche, barre articulée. Pas de pierre transformée en ordinateur.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Marqué","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_fonction-substituee', 'Fonction substituée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA","activation":null,"texte_court":"un élément physiquement adapté devient un composant d''un système surnaturel ou technomagique existant (métal conducteur rituel, cristal d''ancrage, corps-interface). Ni énergie, ni savoir, ni contrôle gratuits.","texte_reference":"Fonction substituéeProfil: 2 PTV • DON • Envahi • R • 1 PAUn élément physiquement approprié devient temporairement composant fonctionnel d’un système surnaturel ou technomagique existant : métal conducteur rituel, cristal support d’ancrage, corps interface biologique. Pas d’énergie, savoir ou contrôle gratuit.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Envahi","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_detourner-la-fonction', 'Détourner la fonction', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA, 1/scène","activation":null,"texte_court":"sur une fonction identifiée, Volonté + Maîtrise spirituelle contre Défense ou Puissance. En réussite, jusqu''à la fin de la prochaine activation, elle passe à un rôle voisin ou parasite (venin inerte, capteur devenu émetteur, régénération en cicatrice rigide). Jamais « cœur → arrêt ».","texte_reference":"Détourner la fonctionProfil: 3 PTV • DON • Envahi • R • 1 PA • 1/ScèneSur une fonction identifiée : Volonté + Maîtrise spirituelle contre Défense/Puissance. En réussite jusqu’à la fin de la prochaine activation, la fonction est réaffectée vers un rôle voisin ou parasite : glande à venin produit inerte, capteur devient émetteur, régénération produit cicatrice rigide. Pas cœur -> arrêt.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Envahi","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_fonction-flottante', 'Fonction flottante', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 2 PA, 1/scène","activation":null,"texte_court":"toi, une cible consentante ou un objet touché recevez une fonction déjà reconnue par un phénomène présent (ancre secondaire, conduit de malédiction, réceptacle, support de frontière). Ne falsifie jamais un nom, un lignage, un consentement, une culpabilité ni un statut divin.","texte_reference":"Fonction flottanteProfil: 3 PTV • DON • Au bord • R • 2 PA • 1/ScèneAttribuer temporairement à soi-même, une cible consentante ou un objet touché une fonction déjà reconnue par un phénomène présent : ancre secondaire, conduit de malédiction, réceptacle valide, support de frontière. Ne falsifie jamais nom, lignage, consentement, culpabilité ou statut divin.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Au bord de la Rupture","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_metastase_le_corps_adaptable', 'Le corps adaptable', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Adaptation préparée ressemble à Spécialisation (Bellatheis) et à Forme de circonstance (Éden Gris) : on garde les trois (A4). Le Don vient de la Corruption, sans Souillure ; les deux Rites coûtent une Souillure ; Forme de circonstance s''applique à autrui."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_metabolisme-de-circonstance', 'Métabolisme de circonstance', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"pour la scène, tu tolères une incompatibilité biologique simple (peu d''oxygène, nourriture inutilisable, atmosphère inhabituelle non corrosive, température extrême non destructrice). Ni vide ni plasma.","texte_reference":"Métabolisme de circonstanceProfil: 1 PTV • DON • Marqué • SR/R • 1 PAPour la scène, réaffecter le métabolisme afin de tolérer une incompatibilité biologique simple : faible oxygène, nourriture inutilisable, atmosphère inhabituelle non corrosive, température extrême non destructrice. Pas de vide ni plasma.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Marqué","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_organe-suppleant', 'Organe suppléant', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"quand tu perds brutalement une fonction biologique non centrale, une autre partie du corps la reprend jusqu''à la fin de ta prochaine activation. Rien ne repousse ; cerveau et âme détruits sont hors de portée.","texte_reference":"Organe suppléantProfil: 2 PTV • DON • Marqué • SR/R • Réaction 1 PA • 1/ScèneLorsqu’une fonction biologique non centrale est brutalement perdue, une autre partie du corps en reprend le rôle jusqu’à la fin de la prochaine activation. La matière détruite ne revient pas ; cerveau/âme totalement détruits sont hors portée.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Marqué","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_adaptation-preparee', 'Adaptation préparée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, R, 1 PA","activation":null,"texte_court":"pour la scène, une adaptation simple (branchies, vision nocturne, filtration d''une famille de toxiques, adhérence, haute pression, membrane oculaire, thermorégulation, électroréception). Une seule active.","texte_reference":"Adaptation préparéeProfil: 2 PTV • DON • Marqué • R • 1 PACréer pour la scène une adaptation biologique simple : branchies, vision nocturne, filtration d’une famille de toxiques, adhérence, haute pression, membrane oculaire, thermorégulation, électroréception. Une seule active.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Marqué","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"correction","changements":"aucun. Adaptation préparée ressemble à Spécialisation (Bellatheis) et à Forme de circonstance (Éden Gris) : on garde les trois (A4). Le Don vient de la Corruption, sans Souillure ; les deux Rites coûtent une Souillure ; Forme de circonstance s''applique à autrui."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_evolution-reactionnelle', 'Évolution réactionnelle', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, Réaction 1 PA, 1/round","activation":null,"texte_court":"après une conséquence non chiffrée venue d''un vecteur physique ou biologique, l''effet se résout puis tu t''adaptes : pour la scène, ce vecteur ne peut plus t''imposer la même Altération par la même méthode. Les dégâts restent possibles.","texte_reference":"Évolution réactionnelleProfil: 2 PTV • DON • Envahi • R • Réaction 1 PA • 1/roundAprès avoir subi une conséquence non purement numérique issue d’un vecteur physique/biologique, l’effet actuel est résolu puis une adaptation spécifique apparaît. Pour la scène, le même vecteur ne peut plus imposer la même Altération par la même méthode ; les dégâts restent possibles.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Envahi","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_morphologie-fonctionnelle', 'Morphologie fonctionnelle', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA","activation":null,"texte_court":"une structure biologique temporaire que ton corps n''avait pas (griffes, membrane de plané, appendice, crochets, écholocation, plaque osseuse, mâchoire). Arme naturelle DGT 4 faute de meilleur profil.","texte_reference":"Morphologie fonctionnelleProfil: 2 PTV • DON • Envahi • R • 1 PACréer une structure biologique temporaire dont le corps ne possédait pas l’équivalent : griffes, membrane de plané, appendice, crochets, écholocation, plaque osseuse, mâchoire. Une arme naturelle vaut DGT 4 si aucun profil plus adapté.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Envahi","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_adaptation-partagee', 'Adaptation partagée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA","activation":null,"texte_court":"au contact d''une créature consentante, tu lui transfères une de tes Adaptations préparées ou Morphologies jusqu''à la fin de la scène. Tu la perds pendant ce temps ; une seule partagée.","texte_reference":"Adaptation partagéeProfil: 2 PTV • DON • Envahi • R • 1 PAAu contact d’une créature consentante, transférer l’une de ses propres Adaptations préparées ou Morphologies fonctionnelles jusqu’à la fin de la scène. Le porteur la perd tant qu’elle est transférée ; une seule partagée.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Envahi","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_reponse-dirigee', 'Réponse dirigée', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, 2 PA, 1/scène","activation":null,"texte_court":"après une confrontation directe avec un phénomène qui t''est inaccessible, tu crées l''interaction adaptée (toucher l''immatériel, suivre un déphasage, interfacer un réseau alien, respirer l''irrespirable). L''interaction devient possible, pas la réussite.","texte_reference":"Réponse dirigéeProfil: 3 PTV • DON • Envahi • R • 2 PA • 1/ScèneAprès confrontation directe à un phénomène fonctionnellement inaccessible, créer une interaction précisément adaptée : toucher une forme immatérielle, suivre un déphasage particulier, interfacer un réseau alien, respirer une atmosphère incompatible. Rend l’interaction possible, pas la réussite automatique.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Envahi","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_contre-evolution', 'Contre-évolution', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 1 PA, 1/scène","activation":null,"texte_court":"après avoir subi ou résisté à un Talent surnaturel précis d''une source précise, tu crées une contre-fonction. Jusqu''à la fin de la scène, elle ne peut plus t''imposer la même conséquence spéciale par ce Talent sans changer de vecteur. Les dégâts bruts restent.","texte_reference":"Contre-évolutionProfil: 3 PTV • DON • Au bord • R • 1 PA • 1/ScèneAprès avoir subi ou résisté à un Talent surnaturel précis d’une Source précise, créer une contre-fonction adaptée. Jusqu’à la fin de la scène, la Source ne peut plus imposer la même conséquence spéciale par ce Talent sans changer réellement son vecteur. Dégâts bruts restent.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Au bord de la Rupture","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_metastase_derniere-fonction', 'Dernière fonction', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction, 1/scénario","activation":null,"texte_court":"au seuil de Mort, ton corps réaffecte ce qui reste pour la seule continuité de l''existence : 0 PV, Stabilisé, avec une Mutation de crise visible. +1 Corruption Vhadhi automatique.","texte_reference":"Dernière fonctionProfil: 3 PTV • DON • Au bord • R • Réaction • 1/ScénarioAu seuil de Mort, le corps réaffecte brutalement ce qu’il reste de physiologie pour assurer uniquement la continuité de l’existence. Tomber à 0 PV Stabilisé et recevoir une Mutation de crise visible appropriée. +1 Corruption Vhadhi automatique.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Métastase","kind":"DON","profondeur":"Au bord de la Rupture","source":"vhadhi","famille":"Métastase","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
