INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_l_eden_gris_le_laboratoire', 'Le laboratoire', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_lire-la-metastase', 'Lire la métastase', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1 PA, Souillure 15","activation":null,"texte_court":"sur une transformation surnaturelle, tu sais si elle est temporaire, entretenue, structurelle ou en stabilisation, et quelle fonction elle cherche à remplir. Ni origine complète ni remède.","texte_reference":"Lire la métastaseProfil: 1 PTV • RITE • SR/R • 1 PA • Souillure 15Sur une transformation surnaturelle examinée, déterminer si elle est temporaire, entretenue, structurelle ou en stabilisation, et la fonction principale qu’elle cherche à accomplir. Pas d’origine complète ni remède automatique.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_matrice-de-nacre', 'Matrice de Nacre', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, R, préparation, Souillure 15","activation":null,"texte_court":"avec une vraie Nacre noire ou un substitut valable, tu prépares une matrice qui conserve une adaptation précise. Le composant n''est pas créé.","texte_reference":"Matrice de NacreProfil: 1 PTV • RITE • R • Préparation • Souillure 15Avec une vraie Nacre noire ou un substitut valable, préparer une matrice capable de conserver une adaptation précise. Le Rite ne crée pas le composant.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_stabiliser-l-evolution', 'Stabiliser l''évolution', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"une transformation temporaire due à Vhadhi, à l''Éden Gris ou à un Talent compatible tient jusqu''à la fin du scénario sans entretien. Une seule par cible ; jamais intrinsèque.","texte_reference":"Stabiliser l’évolutionProfil: 2 PTV • RITE • R • Rituel • Souillure 18Une transformation temporaire provoquée par Vhadhi, l’Éden Gris ou un Talent compatible peut être maintenue jusqu’à la fin du scénario sans entretien. Une seule stabilisée par cible ; pas intrinsèque.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_reversion-dirigee', 'Réversion dirigée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA ou prolongé, Souillure 18","activation":null,"texte_court":"sur une transformation non structurelle de Vhadhi ou de la métastasismancie, tu restaures la fonction d''avant. Si elle est imposée, Volonté + Maîtrise spirituelle contre sa Puissance. Ne retire ni Corruption ni Rupture.","texte_reference":"Réversion dirigéeProfil: 2 PTV • RITE • R • 2 PA ou prolongé • Souillure 18Sur une transformation non structurelle issue de Vhadhi/métastasismancie : restaurer la fonction précédente. Si imposée : Volonté + Maîtrise spirituelle contre Puissance. Ne retire pas la Corruption ni une Rupture.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_causalite-de-remplacement', 'Causalité de remplacement', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel, 1/scène, Souillure 21","activation":null,"texte_court":"quand un système surnaturel, alien, technomagique ou organique manque d''une fonction, un autre composant présent la remplit pour la scène. Ni savoir ni énergie gratuits.","texte_reference":"Causalité de remplacementProfil: 3 PTV • RITE • R • Rituel • 1/Scène • Souillure 21Lorsqu’un système surnaturel, alien, technomagique ou organique possède une fonction manquante, désigner un autre composant physiquement présent pour remplir ce rôle pendant la scène. Pas de connaissance ni énergie gratuite.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
