INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_forme-de-circonstance', 'Forme de circonstance', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 15","activation":null,"texte_court":"une cible consentante reçoit une adaptation simple (du type Adaptation préparée) jusqu''à la fin de la scène. Une seule.","texte_reference":"Forme de circonstanceProfil: 1 PTV • RITE • SR/R • Rituel • Souillure 15Donner à une cible consentante une adaptation simple de type Adaptation préparée jusqu’à la fin de la scène. Une seule.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_correction-fonctionnelle', 'Correction fonctionnelle', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel prolongé, Souillure 18","activation":null,"texte_court":"sur une perte fonctionnelle durable, d''autres tissus reprennent le rôle (son par les os, muscles reconfigurés, fonction glandulaire déplacée). Rien d''absent n''est recréé.","texte_reference":"Correction fonctionnelleProfil: 2 PTV • RITE • R • Rituel prolongé • Souillure 18Sur une perte fonctionnelle durable, réaffecter d’autres tissus pour rendre la fonction possible : transmettre le son par os, reconfigurer des muscles, déplacer une fonction glandulaire. Ne recrée pas matière absente.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_regeneration-dirigee', 'Régénération dirigée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel prolongé, Souillure 18 ; requiert Correction fonctionnelle","activation":null,"texte_court":"avec du temps, des nutriments, de la masse biologique et un milieu contrôlé, tu reconstruis un organe, un œil, un grand tissu ou un membre, en heures ou en jours. Ni résurrection ni PV rendus.","texte_reference":"Régénération dirigéeProfil: 2 PTV • RITE • R • Rituel prolongé • Prérequis : Correction fonctionnelle • Souillure 18Avec temps, nutriments, masse biologique et environnement contrôlé, reconstruire organe, œil, grande portion de tissu ou membre en heures/jours. Pas de résurrection ni récupération automatique de PV.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":"Correction fonctionnelle","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_reponse-guidee', 'Réponse guidée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA, 1/scène, Souillure 18","activation":null,"texte_court":"après qu''une cible consentante a subi un danger biologique, environnemental ou énergétique adaptable, tu provoques une adaptation contre ce vecteur pour la scène. La première exposition est subie en entier.","texte_reference":"Réponse guidéeProfil: 2 PTV • RITE • R • 2 PA • 1/Scène • Souillure 18Après qu’une cible consentante a subi un danger biologique, environnemental ou énergétique adaptable, provoquer une adaptation précisément dirigée contre ce vecteur pour la scène. La première exposition est entièrement subie.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_adaptation-durable', 'Adaptation durable', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 21","activation":null,"texte_court":"la cible garde une adaptation de l''Éden Gris jusqu''à la fin du scénario si elle accepte +1 Corruption Vhadhi automatique. Sinon, l''adaptation disparaît au prochain repos prolongé.","texte_reference":"Adaptation durableProfil: 3 PTV • RITE • R • Rituel • Souillure 21Une cible conserve une adaptation de l’Éden Gris jusqu’à la fin du scénario. En plus de Souillure 21, elle accepte +1 Corruption Vhadhi automatique. Sans cette acceptation, l’adaptation disparaît au prochain repos prolongé.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_mue-successive', 'Mue successive', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, préparation, Souillure 21 ; requiert Adaptation durable","activation":null,"texte_court":"tu prépares deux configurations chez une cible consentante ; pendant la scène, 1 PA fait passer de l''une à l''autre. Chacune reste un ensemble d''adaptations simples déjà disponibles.","texte_reference":"Mue successiveProfil: 3 PTV • RITE • R • Préparation • Prérequis : Adaptation durable • Souillure 21Préparer deux configurations fonctionnelles chez une cible consentante. Pendant la scène, 1 PA permet de passer de l’une à l’autre. Chaque configuration reste un ensemble d’adaptations simples déjà disponibles.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":"Adaptation durable","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_l_eden_gris_la_continuite_de_l_ame', 'La continuité de l''âme', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Nouvelle enveloppe touche au transfert d''âme, comme la Promesse d''Am''Mleeac. Le Rite reste propre à l''Éden Gris : il demande une âme consentante et un corps préparé, alors que la Promesse agit à la mort d''un prêtre."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_retenir-l-ame', 'Retenir l''âme', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, 2 PA, 1/scène, Souillure 18","activation":null,"texte_court":"sur une créature qui vient de mourir, ou dont l''âme quitte le corps, Volonté + Maîtrise spirituelle contre sa Puissance si quelque chose s''y oppose. En réussite, l''âme reste fixée au corps jusqu''à la fin de la scène. Ni résurrection ni action.","texte_reference":"Retenir l’âmeProfil: 2 PTV • RITE • SR/R • 2 PA • 1/Scène • Souillure 18Sur une créature venant de mourir ou dont l’âme quitte le corps : Volonté + Maîtrise spirituelle contre Puissance si opposition. En réussite l’âme reste fixée à ce corps jusqu’à la fin de la scène. Pas de résurrection ni action automatique.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_receptacle-de-continuite', 'Réceptacle de continuité', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel prolongé, Souillure 18","activation":null,"texte_court":"tu prépares un corps vide, un organisme artificiel, un support technomagique ou un contenant comme réceptacle temporaire d''une âme consentante. Ses capacités dépendent du support.","texte_reference":"Réceptacle de continuitéProfil: 2 PTV • RITE • R • Rituel prolongé • Souillure 18Préparer corps vide, organisme artificiel, support technomagique ou contenant capable de soutenir une conscience comme réceptacle temporaire d’une âme consentante. Les capacités dépendent du support.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_nouvelle-enveloppe', 'Nouvelle enveloppe', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel majeur, Souillure 21","activation":null,"texte_court":"tu transfères une âme consentante d''un corps mourant ou d''un réceptacle vers un corps préparé, viable et sans autre conscience. Ce que porte l''âme reste ; ce que portait l''ancienne chair est perdu.","texte_reference":"Nouvelle enveloppeProfil: 3 PTV • RITE • R • Rituel majeur • Souillure 21Transférer une âme consentante depuis corps mourant/réceptacle vers un corps préparé, viable et sans conscience concurrente. Les propriétés portées par l’âme restent ; celles portées par l’ancienne chair non.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"correction","changements":"aucun. Nouvelle enveloppe touche au transfert d''âme, comme la Promesse d''Am''Mleeac. Le Rite reste propre à l''Éden Gris : il demande une âme consentante et un corps préparé, alors que la Promesse agit à la mort d''un prêtre."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_heritage-de-fonction', 'Héritage de fonction', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel majeur, Souillure 21","activation":null,"texte_court":"tu transmets d''un consentant à un autre une fonction surnaturelle externe (gardien de sceau, ancre, dépositaire de pacte, gardien de portail), avec Volonté + Maîtrise spirituelle contre la Puissance du lien. Jamais une Nature, un Talent, un sang, un lignage ou une mémoire.","texte_reference":"Héritage de fonctionProfil: 3 PTV • RITE • R • Rituel majeur • Souillure 21Transmettre d’un consentant à un autre une fonction surnaturelle externe : gardien de sceau, ancre, dépositaire de pacte, gardien de portail. Volonté + Maîtrise spirituelle contre Puissance du lien. Pas de Nature, Talent, sang, lignage ou mémoire.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":null,"source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_vhadhi_eden-gris_ultime-adaptation', 'Ultime Adaptation', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel interdit, cible Au bord, Souillure 21","activation":null,"texte_court":"la cible prend +1 Corruption Vhadhi automatique et bascule si l''Intégrité est atteinte. En cas de Rupture, tu désignes une Finalité générale ; le MJ décide de la créature née.","texte_reference":"Ultime AdaptationProfil: 3 PTV • RITE • R • Rituel interdit • Cible Au bord • Souillure 21Donner +1 Corruption Vhadhi automatique et provoquer la Bascule si l’Intégrité est atteinte. Si Rupture, le praticien désigne une Finalité générale ; le MJ décide de la créature née. Souillure 21 en plus.","lore":null,"groupe_actuel":"C’Thath Vhadhi — Éden Gris","kind":"RITE","profondeur":"Au bord de la Rupture","source":"vhadhi","famille":"Éden Gris","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
