INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_germination_les_germes', 'Les Germes', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"Nid de chair, Engeance-outil et Enfant véritable demandent un Germe, donc **Sang-graine** dans les faits. C''est écrit en une ligne, sans nouveau prérequis."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_sang-graine', 'Sang-graine', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"tu perds 1 PV et produis un Germe, un petit amas vivant sans intelligence, sans PA ni capacité de combat, qui vit jusqu''à la fin de la scène. Il sert de base aux Dons suivants.","texte_reference":"Sang-graineProfil: 1 PTV • DON • Marqué • SR/R • 1 PAPerdre 1 PV et produire un Germe : petit amas vivant sans intelligence, PA ni capacité de combat, survivant normalement jusqu’à la fin de la scène. Il sert de base aux Dons suivants.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Marqué","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"correction","changements":"Nid de chair, Engeance-outil et Enfant véritable demandent un Germe, donc **Sang-graine** dans les faits. C''est écrit en une ligne, sans nouveau prérequis."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_bourgeon-sensoriel', 'Bourgeon sensoriel', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA ; requiert Sang-graine","activation":null,"texte_court":"un Germe devient œil, oreille, récepteur chimique ou vibratoire. Pour 1 PA, tu perçois depuis lui pendant le round s''il est à courte portée. Aucun sens surnaturel gratuit.","texte_reference":"Bourgeon sensorielProfil: 2 PTV • DON • Marqué • SR/R • 1 PA • Prérequis : Sang-graineTransformer un Germe en œil, oreille, récepteur chimique ou vibratoire. Pour 1 PA, percevoir pendant le round depuis ce Bourgeon s’il est à courte portée. Aucun sens surnaturel gratuit.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Marqué","source":"shaoggith","famille":"Germination","prerequis_texte":"Sang-graine","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_nid-de-chair', 'Nid de chair', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, quelques minutes","activation":null,"texte_court":"tu nourris un Germe de biomasse et crées une petite structure vivante fixe pour le scénario (sentinelle, filtre, maintien de tissu, colle, acide faible, fermeture). Elle se détruit comme un petit organisme.","texte_reference":"Nid de chairProfil: 2 PTV • DON • Envahi • R • Quelques minutesNourrir un Germe avec de la biomasse et créer une petite structure vivante fixe pour le scénario : sentinelle sensorielle, filtre, maintien de tissu, colle, acide faible, fermeture biologique. Détruisible comme petit organisme.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Envahi","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"correction","changements":"Nid de chair, Engeance-outil et Enfant véritable demandent un Germe, donc **Sang-graine** dans les faits. C''est écrit en une ligne, sans nouveau prérequis."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_engeance-outil', 'Engeance-outil', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, 2 PA, 1/scène","activation":null,"texte_court":"avec un Germe et de la biomasse, une petite Engeance temporaire éclôt pour une fonction physique simple (ramper et porter, grimper, creuser, surveiller, récupérer, tenir). Aucun PA propre : ses actions significatives utilisent les tiens.","texte_reference":"Engeance-outilProfil: 3 PTV • DON • Envahi • R • 2 PA • 1/ScèneAvec Germe + biomasse, faire éclore une petite Engeance temporaire conçue pour une fonction physique simple : ramper/porter, grimper, creuser, surveiller, récupérer, tenir. Aucun PA propre ; toute action significative utilise les PA du porteur.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Envahi","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"correction","changements":"Nid de chair, Engeance-outil et Enfant véritable demandent un Germe, donc **Sang-graine** dans les faits. C''est écrit en une ligne, sans nouveau prérequis."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_essaim-de-soi', 'Essaim de soi', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 2 PA, 1/scène","activation":null,"texte_court":"des excroissances se détachent et occupent une petite zone pour la scène. Elles rampent, s''infiltrent et forment un réseau sensoriel. Actions significatives sur tes PA ; une attaque de zone adaptée les élimine.","texte_reference":"Essaim de soiProfil: 3 PTV • DON • Au bord • R • 2 PA • 1/ScènePlusieurs excroissances se détachent et occupent une petite zone pour la scène : elles rampent, s’infiltrent dans de petits passages et servent de réseau sensoriel. Toute action significative utilise les PA du porteur ; une attaque de zone adaptée peut les éliminer.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Au bord de la Rupture","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_enfanter-le-besoin', 'Enfanter le besoin', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 2 PA, 1/scène","activation":null,"texte_court":"face à un problème physique ou environnemental concret, tu crées une Engeance temporaire organisée pour une seule fonction qui permet d''agir sur ce problème. Ni Talent copié, ni contre-pouvoir parfait, ni immunité, ni expertise.","texte_reference":"Enfanter le besoinProfil: 3 PTV • DON • Au bord • R • 2 PA • 1/ScèneAprès rencontre d’un problème physique/environnemental concret, créer une Engeance temporaire spécifiquement organisée pour une seule fonction permettant d’interagir avec ce problème. Pas de Talent copié, contre-pouvoir parfait, immunité universelle ou expertise.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Au bord de la Rupture","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_enfant-veritable', 'Enfant véritable', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, rituel prolongé, 1/scénario","activation":null,"texte_court":"avec beaucoup de biomasse, un Germe, plusieurs heures et un milieu adapté, tu engendres un organisme autonome autour d''une Finalité biologique. Le MJ fixe son profil, son instinct et sa personnalité ; aucun contrôle. +1 Corruption Shaoggith automatique.","texte_reference":"Enfant véritableProfil: 3 PTV • DON • Au bord • R • Rituel prolongé • 1/ScénarioAvec beaucoup de biomasse, un Germe, plusieurs heures et un milieu adapté, engendrer un organisme autonome autour d’une Finalité biologique générale. Le MJ crée profil, instinct et personnalité ; aucun contrôle automatique. +1 Corruption Shaoggith automatique.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Au bord de la Rupture","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"correction","changements":"Nid de chair, Engeance-outil et Enfant véritable demandent un Germe, donc **Sang-graine** dans les faits. C''est écrit en une ligne, sans nouveau prérequis."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_germination_la_chair_qui_pousse', 'La chair qui pousse', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun. Chair de remplacement porte déjà son ressort face à Dévorer la vie (Vhodhal) : on construit, on ne dévore pas."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_chair-obstinee', 'Chair obstinée', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, passif","activation":null,"texte_court":"un tissu fraîchement séparé reste vivant et compatible jusqu''à la fin de la scène ; on peut le réimplanter ou s''en servir comme prélèvement. Rien ne se recolle seul.","texte_reference":"Chair obstinéeProfil: 1 PTV • DON • Marqué • SR/R • PassifLes tissus fraîchement séparés restent vivants et compatibles jusqu’à la fin de la scène. Un doigt, œil ou morceau peut encore être réimplanté ou utilisé comme prélèvement ; rien ne se recolle automatiquement.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Marqué","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_chair-de-remplacement', 'Chair de remplacement', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1/scène","activation":null,"texte_court":"tu absorbes au contact assez de biomasse fraîche non hostile et récupères 2 PV. C''est un matériau de construction, pas une dévoration du vivant.","texte_reference":"Chair de remplacementProfil: 2 PTV • DON • Marqué • SR/R • 1/ScèneAbsorber au contact une quantité suffisante de biomasse fraîche non hostile et récupérer 2 PV. Il s’agit de matériau de construction, pas de dévoration de la vie comme Vhodhal.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Marqué","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"correction","changements":"aucun. Chair de remplacement porte déjà son ressort face à Dévorer la vie (Vhodhal) : on construit, on ne dévore pas."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_greffe-immediate', 'Greffe immédiate', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 2 PA","activation":null,"texte_court":"un tissu ou un membre fraîchement perdu et viable est greffé à une créature consentante et remplit grossièrement sa fonction jusqu''à la fin de la scène. Ni PV, ni pouvoir du donneur, ni compatibilité définitive.","texte_reference":"Greffe immédiateProfil: 2 PTV • DON • Marqué • SR/R • 2 PAUn tissu ou membre fraîchement perdu et viable peut être greffé à une créature consentante et remplir grossièrement sa fonction jusqu’à la fin de la scène. Pas de PV rendus, pouvoir du donneur ni compatibilité définitive.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Marqué","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_organe-surnumeraire', 'Organe surnuméraire', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA","activation":null,"texte_court":"un organe simple en plus pour la scène (œil, branchie, glande adhésive, poche de venin, appendice, membrane). Une structure majeure par usage ; ni PA ni attaque en plus.","texte_reference":"Organe surnuméraireProfil: 2 PTV • DON • Envahi • R • 1 PAFaire pousser un organe supplémentaire simple pour la scène : œil, branchie, glande adhésive, poche de venin, appendice, membrane. Une structure majeure par utilisation ; aucun PA ou attaque supplémentaire.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Envahi","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_parasite-reparateur', 'Parasite réparateur', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, préparation","activation":null,"texte_court":"tu cultives un organisme chirurgical placé dans une cible consentante. Après quelques minutes, une Altération physique mineure adaptée disparaît. Ni membre, ni Corruption, ni âme, ni résurrection.","texte_reference":"Parasite réparateurProfil: 2 PTV • DON • Envahi • R • PréparationCultiver un organisme chirurgical introduit dans une cible consentante. Après quelques minutes, une Altération physique mineure appropriée peut être supprimée. Pas de membre entier, Corruption, âme ou résurrection.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Envahi","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_carapace-bourgeonnante', 'Carapace bourgeonnante', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"après une attaque physique qui te touche, des plaques réduisent les dégâts de 3 après Armure, puis se nécrosent et tombent. Les réductions équivalentes ne se cumulent pas.","texte_reference":"Carapace bourgeonnanteProfil: 2 PTV • DON • Envahi • R • Réaction 1 PA • 1/ScèneAprès une attaque physique qui touche, une prolifération de plaques réduit les dégâts de 3 après Armure puis se nécrose et tombe. Les réductions équivalentes ne se cumulent pas.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Envahi","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_semence-corruptrice', 'Semence corruptrice', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, passif","activation":null,"texte_court":"quand une attaque corporelle ou une implantation fait entrer ta propre chair dans l''organisme d''une cible, tu peux l''exposer à Shaoggith (Vigueur + Constitution contre 15), une fois par cible et par scène.","texte_reference":"Semence corruptriceProfil: 3 PTV • DON • Envahi • R • PassifLorsqu’une attaque corporelle ou implantation permet à la propre chair du porteur d’entrer réellement dans l’organisme d’une cible, il peut provoquer une exposition Shaoggith : Vigueur + Constitution difficulté 15, une fois par cible et par scène.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Envahi","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_germination_cocon-de-survie', 'Cocon de survie', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction, 1/scénario","activation":null,"texte_court":"au seuil de Mort, tes tissus essentiels passent dans un Cocon ; ton corps s''effondre et tu es hors combat. Si le Cocon survit jusqu''à la fin de la scène, un nouveau corps incomplet en sort à 0 PV, Stabilisé. +1 Corruption Shaoggith automatique.","texte_reference":"Cocon de survieProfil: 3 PTV • DON • Au bord • R • Réaction • 1/ScénarioAu seuil de Mort, externaliser les tissus essentiels dans un Cocon ; le corps principal s’effondre et le porteur est hors combat. Si le Cocon survit jusqu’à la fin de la scène, un nouveau corps incomplet en sort à 0 PV Stabilisé. +1 Corruption Shaoggith automatique.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Germination","kind":"DON","profondeur":"Au bord de la Rupture","source":"shaoggith","famille":"Germination","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('couche', 'corruption', 'corruption_culte_la_mere_primordiale', 'Culte — la Mère Primordiale', NULL, '{"nature":"corruption","chemin":["Shaoggith — la Germination","Culte — la Mère Primordiale"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_la_mere_primordiale_la_culture', 'La Culture', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_germe-consacre', 'Germe consacré', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 15","activation":null,"texte_court":"avec une trace réelle de Shaoggith ou d''une lignée qui lui est liée, une Culture devient un Germe de la Mère, compatible avec les rites. Aucune Corruption automatique.","texte_reference":"Germe consacréProfil: 1 PTV • RITE • SR/R • Rituel • Souillure 15Avec une trace réelle de Shaoggith ou d’une lignée profondément liée, transformer une Culture en Germe de la Mère compatible avec les rites du culte. Aucun point de Corruption automatique.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_matrice-externe', 'Matrice externe', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"un incubateur (œuf, cuve, poche de chair, matrice technobiologique) remplace une gestation normale. La Culture doit être nourrie, maintenue et protégée.","texte_reference":"Matrice externeProfil: 2 PTV • RITE • R • Rituel • Souillure 18Créer un incubateur biologique — œuf, cuve, poche de chair, matrice technobiologique — capable de remplacer une gestation vivante normale. La Culture doit toujours être nourrie, maintenue et protégée.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_viabilite-impossible', 'Viabilité impossible', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"deux patrimoines biologiques incompatibles produisent une Culture viable. Ni fertilité, ni stabilité, ni pouvoirs garantis.","texte_reference":"Viabilité impossibleProfil: 2 PTV • RITE • R • Rituel • Souillure 18Deux patrimoines biologiques normalement absolument incompatibles peuvent produire une Culture viable. Pas de fertilité future, stabilité ou pouvoirs surnaturels garantis.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_croissance-acceleree', 'Croissance accélérée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"une étape de maturation passe bien plus vite (semaines en jours, jours en heures). Demande énormément de biomasse ; jamais d''un œuf à un Kaiju en quelques secondes.","texte_reference":"Croissance accéléréeProfil: 2 PTV • RITE • R • Rituel • Souillure 18Faire franchir beaucoup plus vite une étape de maturation : semaines vers jours, jours vers heures. Exige énormément de biomasse ; jamais œuf vers Kaiju en quelques secondes.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_stabiliser-la-portee', 'Stabiliser la portée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"une mutation monstrueuse apparue dans une Culture devient un caractère viable au lieu de tuer ou de stériliser. Le rite ne choisit pas la mutation.","texte_reference":"Stabiliser la portéeProfil: 2 PTV • RITE • R • Rituel • Souillure 18Une mutation monstrueuse apparue dans une Culture peut être stabilisée comme caractère viable au lieu de provoquer mort/stérilité. Le rite ne choisit pas la mutation.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_selection-monstrueuse', 'Sélection monstrueuse', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"plusieurs organismes ou variantes entrent en compétition contrôlée ; le MJ dit lequel exprime le mieux un critère biologique choisi (résistance, taille, sens, vitesse de maturation).","texte_reference":"Sélection monstrueuseProfil: 2 PTV • RITE • R • Rituel • Souillure 18Faire entrer plusieurs organismes/variantes en compétition surnaturellement contrôlée. Le MJ indique laquelle exprime le mieux un critère biologique défini : résistance, taille, sens, vitesse de maturation.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_organe-cultive', 'Organe cultivé', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"tu cultives un organe, une peau, une glande, un membre ou une structure pour greffe. Il peut garder une propriété intrinsèque du tissu source, jamais un pouvoir porté par l''âme, un Sang ou une Nature.","texte_reference":"Organe cultivéProfil: 2 PTV • RITE • R • Rituel • Souillure 18Cultiver indépendamment organe, peau, glande, membre ou structure biologique pour greffe. Peut reproduire une propriété biologique intrinsèque du tissu source, pas un pouvoir porté par âme, Sang ou Nature.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_heredite-choisie', 'Hérédité choisie', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 21 ; requiert Viabilité impossible","activation":null,"texte_court":"dans une Culture hybride, tu favorises une propriété biologique ordinaire de chaque lignée (respiration, os, écailles, sens, tolérance, locomotion). Aucun Talent, Nature, Sang ou Mageius.","texte_reference":"Hérédité choisieProfil: 3 PTV • RITE • R • Rituel • Prérequis : Viabilité impossible • Souillure 21Lors d’une Culture hybride, favoriser une propriété biologique ordinaire réelle de chaque lignée : respiration, os, écailles, sens, tolérance, locomotion. Aucun Talent, Nature, Sang ou Mageius automatique.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":"Viabilité impossible","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_elevage-d-abomination', 'Élevage d''Abomination', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel majeur, Souillure 21","activation":null,"texte_court":"avec une Culture, une nurserie ou un laboratoire, du temps, de la nourriture et des composants, tu produis une Abomination durable autour d''une fonction générale. Le MJ fixe son profil ; ni obéissance, ni intelligence, ni puissance garanties.","texte_reference":"Élevage d’AbominationProfil: 3 PTV • RITE • R • Rituel majeur • Souillure 21Avec Culture, nurserie/laboratoire, temps, alimentation et composants, produire une Abomination durable autour d’une fonction générale. Le MJ crée son profil ; aucune obéissance, intelligence ou puissance déterminée n’est garantie.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_la_mere_primordiale_la_couvee', 'La Couvée', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_empreinte-de-couvee', 'Empreinte de Couvée', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 15","activation":null,"texte_court":"pendant la croissance, tu imprimes ta signature. Tu reconnais ensuite la créature comme issue de ta Couvée malgré ses changements. Ni localisation ni contrôle.","texte_reference":"Empreinte de CouvéeProfil: 1 PTV • RITE • SR/R • Rituel • Souillure 15Pendant la croissance, imprimer la signature du cultivateur. Il peut ensuite reconnaître surnaturellement la créature comme issue de sa Couvée malgré modifications/croissance. Pas de localisation ni contrôle.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_instinct-imprime', 'Instinct imprimé', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"pendant la gestation, tu installes un impératif simple (protéger un lieu, épargner certaines signatures, fuir le feu, rapporter une proie, chercher une substance). Une créature intelligente peut apprendre à le contourner.","texte_reference":"Instinct impriméProfil: 2 PTV • RITE • R • Rituel • Souillure 18Introduire durant la gestation un impératif comportemental simple : protéger un lieu, épargner certaines signatures, fuir le feu, rapporter une proie, chercher une substance. Une créature intelligente peut apprendre à le contourner.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_appel-de-la-couvee', 'Appel de la Couvée', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, 1 PA, Souillure 18","activation":null,"texte_court":"les créatures de ton Empreinte, dans une zone locale, perçoivent un appel simple : venir, fuir, danger, nid. Ni télépathie complexe, ni GPS, ni téléportation.","texte_reference":"Appel de la CouvéeProfil: 2 PTV • RITE • SR/R • 1 PA • Souillure 18Les créatures marquées par l’Empreinte dans une zone locale perçoivent immédiatement un appel simple : venir, fuir, danger, nid. Pas de télépathie complexe, GPS ou téléportation.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_organisme-d-assaut', 'Organisme d''assaut', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, R, rituel, Souillure 18","activation":null,"texte_court":"à la conception d''une Abomination, tu lui donnes une structure de combat (projection, acide, venin, griffes, projectile organique, protection). Profil défini avec le MJ.","texte_reference":"Organisme d’assautProfil: 2 PTV • RITE • R • Rituel • Souillure 18Lors de la conception d’une Abomination, lui donner une structure biologique explicitement destinée à projection, acide, venin, griffes, projectile organique ou protection. Profil défini avec le MJ selon la Culture.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_main-de-la-mere', 'Main de la Mère', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, 1 PA, Souillure 21","activation":null,"texte_court":"une créature de ta Couvée qui accepte encore l''Empreinte fait une action tactique simple. Le PA est le tien ; elle utilise ses propres valeurs.","texte_reference":"Main de la MèreProfil: 3 PTV • RITE • R • 1 PA • Souillure 21Sur une créature de sa propre Couvée qui accepte encore l’Empreinte, lui faire accomplir une action tactique simple. Le PA est dépensé par le cultivateur ; la créature utilise ses propres valeurs.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_shaoggith_mere-primordiale_dechainer-la-portee', 'Déchaîner la portée', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, 2 PA, 1/scène, Souillure 21","activation":null,"texte_court":"tu lèves les inhibitions d''une créature de ta Couvée. Jusqu''à la fin de sa prochaine activation, elle use de sa fonction prédatrice la plus extrême ; ensuite, tu perds ton contrôle rituel sur elle pour le reste de la scène.","texte_reference":"Déchaîner la portéeProfil: 3 PTV • RITE • R • 2 PA • 1/Scène • Souillure 21Libérer temporairement les inhibitions biologiques placées sur une créature de sa Couvée. Jusqu’à la fin de sa prochaine activation, elle utilise sa fonction prédatrice la plus extrême ; ensuite le cultivateur perd son contrôle rituel sur elle pour le reste de la scène.","lore":null,"groupe_actuel":"Gajh’Shaoggith — Mère Primordiale","kind":"RITE","profondeur":null,"source":"shaoggith","famille":"Mère Primordiale","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
