INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_fixation_ce_qui_ne_change_pas', 'Ce qui ne change pas', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_age-sans-prise', 'Âge sans prise', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, passif","activation":null,"texte_court":"tant que tu as au moins 1 Corruption Thul, ton vieillissement naturel est suspendu. Purifié, tu reprends à partir de ton état actuel, sans rattrapage.","texte_reference":"Âge sans priseProfil: 1 PTV • DON • Marqué • SR/R • PassifTant que le personnage possède au moins 1 Corruption Thul, son vieillissement biologique naturel est suspendu. À purification complète, il reprend normalement à partir de l’état actuel ; aucun vieillissement rétroactif.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Marqué","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_memoire-fossile', 'Mémoire fossile', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"tu fixes un souvenir réellement possédé. Jusqu''à ce que tu en fixes un autre, aucune correction surnaturelle ordinaire ne peut le modifier ; une attaque extraordinaire doit vaincre ta Volonté + Maîtrise spirituelle. Ne récupère ni n''invente rien.","texte_reference":"Mémoire fossileProfil: 1 PTV • DON • Marqué • SR/R • 1 PAFixer un souvenir précis réellement possédé. Jusqu’à ce qu’un autre soit fixé, une correction surnaturelle ordinaire ne peut le modifier/effacer ; une attaque extraordinaire peut tenter Volonté + Maîtrise spirituelle contre Puissance. Ne récupère ni n’invente un souvenir.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Marqué","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_ancrage-immobile', 'Ancrage immobile', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, Réaction 1 PA, 1/round","activation":null,"texte_court":"jusqu''au début de ta prochaine activation, une force humaine ordinaire ne peut pas te projeter, te renverser ni t''entraîner. Le support peut casser ; une force extraordinaire peut vaincre ta Volonté + Maîtrise spirituelle.","texte_reference":"Ancrage immobileProfil: 2 PTV • DON • Marqué • SR/R • Réaction 1 PA • 1/roundJusqu’au début de la prochaine activation, une force humaine ordinaire ne peut normalement pas projeter, renverser ou entraîner le porteur. Le support peut casser ; une force extraordinaire peut vaincre Volonté + Maîtrise spirituelle.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Marqué","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_constante-temporelle', 'Constante temporelle', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, SR/R, passif","activation":null,"texte_court":"tout effet surnaturel qui veut te vieillir, te rajeunir, accélérer ta dégradation ou changer ta vitesse temporelle doit vaincre ta Volonté + Maîtrise spirituelle, même sans défense prévue.","texte_reference":"Constante temporelleProfil: 2 PTV • DON • Envahi • SR/R • PassifTout effet surnaturel cherchant à faire vieillir, rajeunir, accélérer la dégradation ou modifier directement la vitesse temporelle personnelle doit vaincre Volonté + Maîtrise spirituelle même s’il n’offrait normalement pas de défense individuelle.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Envahi","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_stase-parfaite', 'Stase parfaite', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 2 PA, 1/scène","activation":null,"texte_court":"tu places en Stase, jusqu''au début de ta prochaine activation, toi-même ou une cible consentante ou totalement impuissante. Elle n''a plus d''action, de perception active, de soin, de dommage matériel ordinaire, d''évolution d''état ni de transformation. Une puissance supérieure peut rompre la Stase contre ta Volonté + Maîtrise spirituelle.","texte_reference":"Stase parfaiteProfil: 3 PTV • DON • Au bord • R • 2 PA • 1/ScèneToucher soi-même, une cible consentante ou totalement impuissante et la placer en Stase jusqu’au début de la prochaine activation : aucune action, perception active, soin, dommage matériel ordinaire, progression d’état ou transformation. Une puissance supérieure peut tenter de rompre contre Volonté + Maîtrise spirituelle.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Au bord de la Rupture","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_dernier-instant', 'Dernier instant', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, Réaction, 1/scénario","activation":null,"texte_court":"au seuil de Mort, ton corps se fixe dans son dernier état compatible avec la vie : 0 PV, Stabilisé, en Stase jusqu''à la fin de la scène ou une sortie appropriée. +1 Corruption Thul automatique ; Bascule à la sortie si besoin.","texte_reference":"Dernier instantProfil: 3 PTV • DON • Au bord • R • Réaction • 1/ScénarioAu seuil de Mort, fixer le corps dans le dernier état compatible avec sa continuité. Tomber à 0 PV Stabilisé et entrer en Stase jusqu’à la fin de la scène ou sortie appropriée. +1 Corruption Thul automatique ; Test de Bascule à la sortie si nécessaire.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Au bord de la Rupture","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_dons_de_la_fixation_figer_le_monde', 'Figer le monde', NULL, '{"nature":"corruption","forme":"dons","forme_lot":"Dons","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_conserver-l-etat', 'Conserver l''état', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA","activation":null,"texte_court":"au contact d''un petit objet ou échantillon non vivant, son évolution passive (coagulation, évaporation, rouille, refroidissement, décomposition) s''arrête jusqu''à la fin de la scène. On peut toujours le détruire.","texte_reference":"Conserver l’étatProfil: 2 PTV • DON • Marqué • SR/R • 1 PAAu contact d’un petit objet/échantillon non vivant, suspendre son évolution physique passive jusqu’à la fin de la scène : coagulation, évaporation, rouille, refroidissement, décomposition. Une destruction volontaire reste possible.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Marqué","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_suspendre-la-degradation', 'Suspendre la dégradation', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Marqué, SR/R, 1 PA, 1/scène","activation":null,"texte_court":"sur toi ou une cible consentante, une hémorragie, une infection, une maladie, un poison progressif ou une nécrose déjà actifs n''empirent plus jusqu''à la fin de la scène. Rien n''est guéri.","texte_reference":"Suspendre la dégradationProfil: 2 PTV • DON • Marqué • SR/R • 1 PA • 1/ScèneSur soi ou une cible consentante, choisir hémorragie, infection, maladie, poison progressif, nécrose ou détérioration équivalente déjà active. Jusqu’à la fin de la scène, elle n’empire plus. Rien n’est guéri.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Marqué","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_processus-suspendu', 'Processus suspendu', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, SR/R, 1 PA, 1/scène","activation":null,"texte_court":"tu figes un processus continu observé (combustion, corrosion, régénération, transformation, propagation, croissance, effondrement) jusqu''à la fin de la prochaine activation de sa source ou de sa cible. S''il y a opposition, Volonté + Maîtrise spirituelle contre Défense ou Puissance.","texte_reference":"Processus suspenduProfil: 2 PTV • DON • Envahi • SR/R • 1 PA • 1/ScèneChoisir un processus continu observable/identifié : combustion, corrosion, régénération, transformation, propagation, croissance, effondrement. Si opposition : Volonté + Maîtrise spirituelle contre Défense/Puissance. En réussite, le processus est figé jusqu’à la fin de la prochaine activation de sa source/cible.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Envahi","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_blessure-immuable', 'Blessure immuable', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1/scène","activation":null,"texte_court":"après avoir infligé au moins 1 PV réel, tu fixes la blessure. Jusqu''à la fin de la prochaine activation de la cible, ces PV ne reviennent ni par Régénération ni par guérison surnaturelle.","texte_reference":"Blessure immuableProfil: 2 PTV • DON • Envahi • R • 1/ScèneAprès avoir infligé au moins 1 PV réel, fixer cette blessure. Jusqu’à la fin de la prochaine activation de la cible, cette perte ne peut être récupérée par Régénération ou guérison surnaturelle.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Envahi","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_figer-l-effet', 'Figer l''effet', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"Envahi, R, 1 PA, 1/scène","activation":null,"texte_court":"sur un phénomène surnaturel actif, Volonté + Maîtrise spirituelle contre sa Puissance. En réussite, jusqu''à la fin de la prochaine activation de sa source, ses paramètres sont fixés : ni nouvelle cible, ni déplacement de zone, ni extension, ni contraction, ni changement de mode.","texte_reference":"Figer l’effetProfil: 2 PTV • DON • Envahi • R • 1 PA • 1/ScèneSur un phénomène surnaturel actif perçu : Volonté + Maîtrise spirituelle contre Puissance. En réussite jusqu’à la fin de la prochaine activation de sa Source, ses paramètres présents sont fixés : pas de nouvelle cible, déplacement de zone, extension, contraction ou changement de mode.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Envahi","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_interdire-la-mue', 'Interdire la mue', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, R, Réaction 1 PA, 1/scène","activation":null,"texte_court":"quand une créature perçue change de forme, quitte son corps, devient immatérielle, change d''hôte ou se métamorphose, Volonté + Maîtrise spirituelle contre son résultat ou sa Puissance. En réussite, l''activation échoue et ses coûts sont consommés.","texte_reference":"Interdire la mueProfil: 3 PTV • DON • Envahi • R • Réaction 1 PA • 1/ScèneQuand une créature perçue active changement de forme, abandon du corps, immatérialité, changement d’hôte ou métamorphose immédiate : Volonté + Maîtrise spirituelle contre résultat/Puissance. En réussite l’activation échoue et ses coûts sont consommés.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Envahi","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_archive-abyssale', 'Archive abyssale', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Envahi, SR/R, rituel","activation":null,"texte_court":"tu fixes l''état de Vérité d''un document, d''un petit objet, d''une inscription ou d''un enregistrement. Tant qu''il reste intact, ni les corrections ordinaires de l''Hologramme ni les altérations diffuses ne le réécrivent. Une intervention ciblée, une destruction ou un piratage réel restent possibles.","texte_reference":"Archive abyssaleProfil: 3 PTV • DON • Envahi • SR/R • RituelFixer l’état de Vérité d’un document, petit objet, inscription ou enregistrement. Tant qu’il reste intact, corrections ordinaires de l’Hologramme et altérations diffuses ne le réécrivent pas. Une intervention ciblée, destruction ou piratage réel reste possible.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Envahi","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_fixation_rien-ne-change', 'Rien ne change', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"Au bord, R, 2 PA, 1/scène","activation":null,"texte_court":"jusqu''au début de ta prochaine activation, une petite zone est en Inertie thulienne. Toute métamorphose, dématérialisation, régénération, altération temporelle ou téléportation par changement d''état doit d''abord vaincre ta Volonté + Maîtrise spirituelle.","texte_reference":"Rien ne changeProfil: 3 PTV • DON • Au bord • R • 2 PA • 1/ScèneJusqu’au début de la prochaine activation, une petite zone subit Inertie thulienne. Toute capacité surnaturelle de métamorphose, dématérialisation, régénération, altération temporelle ou téléportation par changement d’état doit d’abord vaincre Volonté + Maîtrise spirituelle du porteur, puis se résoudre normalement.","lore":null,"groupe_actuel":"Thul — Fixation","kind":"DON","profondeur":"Au bord de la Rupture","source":"thul","famille":"Fixation","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
