INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_le_sombre_culte_commun_le_patron_des_profondeurs', 'Le Patron des profondeurs', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_sombre-culte-commun_rite-de-conservation', 'Rite de Conservation', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 15","activation":null,"texte_court":"un cadavre, un sanctuaire, un objet rituel, un échantillon ou un composant reste un mois dans son état présent : pas de décomposition, d''altération ordinaire ni de perte naturelle de charge. Une intervention directe peut le détruire.","texte_reference":"Rite de ConservationProfil: 1 PTV • RITE • SR/R • Rituel • Souillure 15Préparer cadavre, sanctuaire, objet rituel, échantillon ou composant surnaturel pour qu’il reste dans son état présent pendant un mois : pas de décomposition, altération ordinaire ou perte naturelle de charge passive. Une intervention directe peut le détruire.","lore":null,"groupe_actuel":"Thul — Sombre Culte commun","kind":"RITE","profondeur":null,"source":"thul","famille":"Sombre Culte commun","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_sombre-culte-commun_corps-du-peuple', 'Corps du peuple', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, SR/R, 1 PA, Souillure 18 ; Patron réel","activation":null,"texte_court":"pour la scène, une caractéristique biologique simple du peuple de ton Patron (branchies, pression, membrane, mucus, sens aquatique). Une seule.","texte_reference":"Corps du peupleProfil: 2 PTV • FAVEUR • SR/R • 1 PA • Patron réel requis • Souillure 18Manifester pour la scène une caractéristique biologique simple du peuple du Patron : branchies, pression, membrane, mucus, sens aquatique. Une seule ; la Faveur dort si le lien disparaît.","lore":null,"groupe_actuel":"Thul — Sombre Culte commun","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Sombre Culte commun","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_sombre-culte-commun_offrande-suspendue', 'Offrande suspendue', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"RITE, SR/R, rituel, Souillure 18","activation":null,"texte_court":"si une victime volontaire, impuissante et préparée meurt pendant le rite, son âme reste ancrée au lieu quelques minutes. Rien n''est volé, mais un sacrifice, un transfert ou une intervention du Patron deviennent possibles.","texte_reference":"Offrande suspendueProfil: 2 PTV • RITE • SR/R • Rituel • Souillure 18Sur une victime volontaire, impuissante et préparée, si elle meurt pendant le rite son âme/essence reste ancrée quelques minutes dans le lieu. Le Rite ne vole rien à lui seul mais permet sacrifice, transfert ou intervention d’un Patron.","lore":null,"groupe_actuel":"Thul — Sombre Culte commun","kind":"RITE","profondeur":null,"source":"thul","famille":"Sombre Culte commun","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_sombre-culte-commun_savoir-noye', 'Savoir noyé', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, SR/R, 1/scénario, Souillure 18","activation":null,"texte_court":"par un sanctuaire lié au Patron, tu demandes un fait concret qu''il connaît. La réponse est vraie, peut-être incomplète, limitée à son savoir.","texte_reference":"Savoir noyéProfil: 2 PTV • FAVEUR • SR/R • 1/Scénario • Souillure 18Par un sanctuaire réellement lié au Patron, demander un fait concret inaccessible normalement mais réellement connu de lui. La réponse est factuellement vraie, possiblement incomplète et limitée par les connaissances du Patron.","lore":null,"groupe_actuel":"Thul — Sombre Culte commun","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Sombre Culte commun","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_sombre-culte-commun_heredite-abyssale', 'Hérédité abyssale', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"RITE, R, rituel prolongé, Souillure 21 ; requiert Corps du peuple","activation":null,"texte_court":"une caractéristique biologique simple de la lignée du Patron devient définitive (une seule chez un PJ). +1 Corruption Thul automatique.","texte_reference":"Hérédité abyssaleProfil: 3 PTV • RITE • R • Rituel prolongé • Prérequis : Corps du peuple • Souillure 21Stabiliser définitivement une caractéristique biologique simple de la lignée du Patron. Une seule Hérédité permanente chez un PJ normal. Souillure 21 +1 Corruption Thul automatique.","lore":null,"groupe_actuel":"Thul — Sombre Culte commun","kind":"RITE","profondeur":null,"source":"thul","famille":"Sombre Culte commun","prerequis_texte":"Corps du peuple","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_sombre-culte-commun_tombe-vivante', 'Tombe vivante', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, R, rituel, Souillure 21","activation":null,"texte_court":"le Patron maintient un cultiste consentant en suspension durable : ni vieillissement ni mort naturelle, presque aucune perception ni action. Il se réveille selon des conditions prévues.","texte_reference":"Tombe vivanteProfil: 3 PTV • FAVEUR • R • Rituel • Souillure 21Le Patron maintient un cultiste consentant en suspension surnaturelle durable : pas de vieillissement ni mort naturelle, presque aucune perception ou action. Réveil selon conditions prévues.","lore":null,"groupe_actuel":"Thul — Sombre Culte commun","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Sombre Culte commun","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
