INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_dagon_la_lumiere_des_abysses', 'La lumière des abysses', NULL, '{"nature":"corruption","forme":"une_porte","forme_lot":"collection à une porte","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_dagon_lueur-froide', 'Lueur froide', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1 PA, Souillure 15","activation":null,"texte_court":"une bioluminescence thulienne sous ta peau. Tu vois dans l''obscurité sous-marine, et une transformation surnaturelle que tu observes ne peut plus se cacher par la seule obscurité ou un camouflage visuel. Pas de Vision de Vérité.","texte_reference":"Lueur froideProfil: 1 PTV • FAVEUR • R • 1 PA • Souillure 15Bioluminescence thulienne sous la peau. Permet de percevoir dans l’obscurité sous-marine et empêche une transformation surnaturelle directement observée de se cacher par simple obscurité/camouflage visuel. Pas de Vision de Vérité.","lore":null,"groupe_actuel":"Thul — Dagon","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Dagon","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_dagon_halo-immobile', 'Halo immobile', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1 PA, 1/scène, Souillure 18","activation":null,"texte_court":"à courte portée, Volonté + Maîtrise spirituelle contre Défense occulte. En réussite, jusqu''à la fin de sa prochaine activation, la cible ne peut plus changer de position par un Déplacement, normal ou surnaturel. Elle peut agir, attaquer, se défendre et manipuler.","texte_reference":"Halo immobileProfil: 2 PTV • FAVEUR • R • 1 PA • 1/Scène • Souillure 18À courte portée : Volonté + Maîtrise spirituelle contre Défense occulte. En réussite jusqu’à la fin de la prochaine activation, la cible ne peut volontairement changer de position par Déplacement normal ou surnaturel, mais peut agir, attaquer, défendre et manipuler.","lore":null,"groupe_actuel":"Thul — Dagon","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Dagon","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_dagon_eternite-des-profondeurs', 'Éternité des profondeurs', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, SR/R, passif, Souillure 21","activation":null,"texte_court":"tant que ton lien avec Dagon tient, ton vieillissement est suspendu, les maladies ordinaires presque figées, et de longues torpeurs sont possibles dans les profondeurs. Tu peux toujours être tué. Souillure seulement quand un effet significatif intervient.","texte_reference":"Éternité des profondeursProfil: 3 PTV • FAVEUR • SR/R • Passif • Souillure 21Tant que le lien avec Dagon est intact : vieillissement naturel suspendu, maladies ordinaires presque figées et longues torpeurs possibles dans les profondeurs. Le personnage peut toujours être tué. Souillure 21 seulement lorsqu’un effet significatif de cette Faveur intervient.","lore":null,"groupe_actuel":"Thul — Dagon","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Dagon","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_dagon_tombe-abyssale', 'Tombe abyssale', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, R, Réaction, 1/scénario, Souillure 21","activation":null,"texte_court":"si tu devais mourir totalement immergé, ou au contact d''une eau rituellement liée à Dagon, tu entres à 0 PV en Stase abyssale, pour très longtemps si rien ne t''en tire. +1 Corruption Thul automatique.","texte_reference":"Tombe abyssaleProfil: 3 PTV • FAVEUR • R • Réaction • 1/Scénario • Souillure 21Si le cultiste devrait mourir totalement immergé ou au contact d’une eau rituellement liée à Dagon, entrer à 0 PV en Stase abyssale. Souillure 21 +1 Corruption Thul automatique. Le corps peut rester ainsi très longtemps.","lore":null,"groupe_actuel":"Thul — Dagon","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Dagon","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
