INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('voie', 'corruption', 'corruption_culte_telipinu_le_reseau_de_mucus', 'Le réseau de mucus', NULL, '{"nature":"corruption","forme":"progression","forme_lot":"progression","verrou":"ordre_paliers","portes":null,"identite":null,"profil":null,"changements":"aucun."}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_telipinu_marque-visqueuse', 'Marque visqueuse', NULL, '{"nature":"corruption","cout":1,"cout_actuel":1,"palier":"I","porte":null,"palier_double":null,"acces":"FAVEUR, SR/R, 1 PA, Souillure 15","activation":null,"texte_court":"ton mucus marque une surface, un objet ou un passage. Jusqu''à la fin de la scène, tu sais si une créature significative l''a traversé ou fortement perturbé, sans savoir qui ni où elle va.","texte_reference":"Marque visqueuseProfil: 1 PTV • FAVEUR • SR/R • 1 PA • Souillure 15Produire du mucus surnaturel et marquer surface, objet ou passage. Jusqu’à la fin de la scène, savoir si une créature significative a traversé ou fortement perturbé la Marque. Pas qui ni où elle va.","lore":null,"groupe_actuel":"Thul — Telipinu","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Telipinu","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_telipinu_reseau-myxinien', 'Réseau myxinien', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1 PA, Souillure 18 ; requiert Marque visqueuse","activation":null,"texte_court":"tu maintiens jusqu''à 3 Marques. Pour 1 PA, tu perçois sons et vibrations autour de l''une pendant le round. Le réseau doit rester continu (humidité, mucus, eau, installation rituelle).","texte_reference":"Réseau myxinienProfil: 2 PTV • FAVEUR • R • 1 PA • Prérequis : Marque visqueuse • Souillure 18Maintenir jusqu’à 3 Marques. Pour 1 PA, percevoir sons et vibrations autour de l’une pendant le round. Le réseau doit rester physiquement continu par humidité, mucus, eau connectée ou installation rituelle.","lore":null,"groupe_actuel":"Thul — Telipinu","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Telipinu","prerequis_texte":"Marque visqueuse","statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_telipinu_voix-dans-la-vase', 'Voix dans la vase', NULL, '{"nature":"corruption","cout":2,"cout_actuel":2,"palier":"II","porte":null,"palier_double":null,"acces":"FAVEUR, R, 1 PA, Souillure 18","activation":null,"texte_court":"tu parles et écoutes à travers une Marque du réseau. Une créature au contact du mucus entend ta voix venir du conduit, du mur, ou presque de sa propre gorge.","texte_reference":"Voix dans la vaseProfil: 2 PTV • FAVEUR • R • 1 PA • Souillure 18Parler et écouter à travers une Marque du réseau. Une créature en contact avec le mucus entend la voix comme venant du conduit, du mur ou presque de sa propre gorge.","lore":null,"groupe_actuel":"Thul — Telipinu","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Telipinu","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('talent', 'corruption', 'fleau_thul_telipinu_chapelle-captive', 'Chapelle captive', NULL, '{"nature":"corruption","cout":3,"cout_actuel":3,"palier":"III","porte":null,"palier_double":null,"acces":"FAVEUR, R, rituel, Souillure 21","activation":null,"texte_court":"dans un sanctuaire préparé, les prières, invocations et appels adressés à une puissance extérieure sont interceptés par le réseau. Bloque ce qui demande une réponse extérieure, pas les Talents propres d''un être déjà présent.","texte_reference":"Chapelle captiveProfil: 3 PTV • FAVEUR • R • Rituel • Souillure 21Dans un sanctuaire préparé, les prières, invocations et appels volontaires adressés à une puissance surnaturelle extérieure sont interceptés par le réseau. Bloque communication/faveur nécessitant une réponse externe, pas les Talents intrinsèques d’un être déjà présent.","lore":null,"groupe_actuel":"Thul — Telipinu","kind":"FAVEUR","profondeur":null,"source":"thul","famille":"Telipinu","prerequis_texte":null,"statut_regle":"origine","changements":null}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
